def analyzer_spot(name, paths, monsters, *, aggressive=0):
    """One farming-analyzer result in its JSON shape."""
    return {"path": "|".join(paths), "name": name, "region": "test",
            "map_paths": ["maps" + path for path in paths], "monsters": list(monsters),
            "xp_hour": 1.0, "money_hour": 1.0, "loot_hour": 1.0, "danger": 1.0,
            "aggressive_spawns": aggressive}


class RouteDeathReachIsolation:
    """Mixin for tests that record route deaths.

    Route-death reach (navigation._reach_cache) is cached per process and
    rate limited (navigation._reach_search_after): every test starts and
    ends with neither, whatever ran before it, and searches are not rate
    limited unless a test patches the interval back.
    """

    def setUp(self):
        from . import navigation

        super().setUp()

        def reset():
            navigation._reach_cache.clear()
            navigation._reach_search_after[0] = 0.0

        reset()
        self.addCleanup(reset)
        patcher = patch.object(navigation, "ROUTE_DEATH_SEARCH_INTERVAL_SECONDS", 0.0)
        patcher.start()
        self.addCleanup(patcher.stop)


class StubAnalyzer:
    """A finished farming analyzer with fixed rankings per objective."""

    def __init__(self, rankings):
        self.rankings = rankings
        self.status = "ready"

    def ranking(self, objective):
        return list(self.rankings.get(objective, ()))

    def snapshot(self, objective, ranked=None):
        ranked = self.ranking(objective) if ranked is None else ranked
        return {"status": self.status, "objective": objective,
                "ranking": ranked[:5]}


