def item_packet(location, items, *, clear=None):
    """An ITEM packet as server/src/socket/item.c writes it.

    ``items`` None is esrv_close_container: only the inventory to delete.
    """
    packet = Packet(0)
    if clear is not None:
        packet.u8(1).u32(clear)
    else:
        packet.u8(0)
    if items is None:
        return packet
    packet.u32(location).u8(1)
    for tag, name in items:
        packet.u32(tag).u32(0).u32(1000).u16(1).u8(0)
        if location > 0:
            packet.u8(0).u8(0).u8(255)  # type, subtype, unidentified
        packet.string(name).u16(0).u8(0).u32(1).string("").u8(0)
    return packet


class ProtocolTests(unittest.TestCase):
    def test_full_player_inventory_packet_releases_replay_barrier(self):
        async def scenario():
            client = AtrinikClient(ClientConfig())

            async def request_quests():
                return None

            client.request_quests = request_quests
            client.load_character_memory = lambda _name: None
            player = Packet(0).u32(7).u32(0).u32(0).string("Sera")
            await client._handle_player(
                Cursor(bytes(player.data)), bytes(player.data))
            self.assertFalse(client.state.inventory_replay_complete)

            client.state.place_item(
                Item(9, item_type=c.TYPE_SKILL, name="slash weapons"), 7)
            # One empty delete-and-replace packet is still a complete
            # authoritative inventory.
            packet = Packet(0).u8(1).u32(7).u32(7).u8(1)
            await client._handle_item(
                Cursor(bytes(packet.data)), bytes(packet.data))

            self.assertTrue(client.state.inventory_replay_complete)
            self.assertEqual(client.state.inventory, [])

        asyncio.run(scenario())

    def test_a_cure_outside_the_bot_resets_the_depletion_count(self):
        async def scenario():
            client = AtrinikClient(ClientConfig())
            client.state.player_tag = 7
            client._persist_character_memory = lambda: None
            force = Item(22, item_type=c.TYPE_FORCE, name="depletion")
            client.state.place_item(force, 7)
            client.state.place_item(Item(23, name="apple"), 7)
            client.set_depletion_points(32)
            delete = Packet(0).u32(23)
            await client._handle_item_delete(
                Cursor(bytes(delete.data)), bytes(delete.data))
            self.assertEqual(client.state.depletion_points, 32)
            # The force itself goes: cured by an item or the dashboard.
            delete = Packet(0).u32(22)
            await client._handle_item_delete(
                Cursor(bytes(delete.data)), bytes(delete.data))
            self.assertEqual(client.state.depletion_points, 0)
            # A new loss counted before its force arrives survives unrelated
            # deletions, so a fresh episode starts from one.
            client.set_depletion_points(1)
            client.state.place_item(Item(24, name="pear"), 7)
            delete = Packet(0).u32(24)
            await client._handle_item_delete(
                Cursor(bytes(delete.data)), bytes(delete.data))
            self.assertEqual(client.state.depletion_points, 1)
            # Cured while offline: the replay on login has no force.
            client.set_depletion_points(32)
            replay = Packet(0).u8(1).u32(7).u32(7).u8(1)
            await client._handle_item(
                Cursor(bytes(replay.data)), bytes(replay.data))
            self.assertEqual(client.state.depletion_points, 0)

        asyncio.run(scenario())

    def test_client_checkpoint_wakes_read_loop_for_clean_reconnect(self):
        class Writer:
            def __init__(self):
                self.closed = False

            def close(self):
                self.closed = True

            async def wait_closed(self):
                pass

        client = AtrinikClient(ClientConfig(account="a", password="b"))
        client.reader = object()
        writer = Writer()
        client.writer = writer
        client.state.phase = "playing"

        self.assertTrue(asyncio.run(client.checkpoint_reconnect()))
        self.assertTrue(client._reconnect_requested)
        self.assertTrue(writer.closed)
        self.assertIsNone(client.reader)
        self.assertIsNone(client.writer)
        self.assertEqual(client.state.phase, "disconnected")

    def test_stalled_send_forces_reconnect_without_killing_task(self):
        class Writer:
            def __init__(self):
                self.closed = False
                self.payload = b""

            def write(self, payload):
                self.payload = payload

            async def drain(self):
                await asyncio.sleep(3600)  # flow control never drains

            def close(self):
                self.closed = True

            async def wait_closed(self):
                pass

        async def run():
            client = AtrinikClient(ClientConfig(connect_timeout=0.01))
            client.SEND_STALL_SECONDS = 0.01
            writer = Writer()
            client.writer = writer
            client.state.phase = "playing"
            await client.command("/time")
            self.assertTrue(writer.payload)
            self.assertTrue(writer.closed)
            self.assertIsNone(client.writer)
            self.assertTrue(client._reconnect_requested)
            self.assertEqual(client.state.phase, "disconnected")
            self.assertEqual(
                client.action_history[-1]["action"], "transport-reconnect")

        asyncio.run(run())

    def test_she_sends_keepalives_while_playing_and_never_answers_an_echo(self):
        # Live, she never sent one: the server's 10-minute idle timeout
        # dropped her 83 times a day. The server echoes each one with its
        # id, so answering the echo would ping-pong.
        class Writer:
            def __init__(self):
                self.payloads = []

            def write(self, payload):
                self.payloads.append(bytes(payload))

            async def drain(self):
                pass

            def close(self):
                pass

            async def wait_closed(self):
                pass

        async def run():
            client = AtrinikClient(ClientConfig(reconnect=False))
            client.KEEPALIVE_SECONDS = (0.01, 0.01)
            writer = Writer()

            async def connect():
                client.writer = writer
                client.state.phase = "playing"

            async def read_loop():
                await asyncio.sleep(0.1)
                raise ConnectionError("dropped")

            client.connect = connect
            client._read_loop = read_loop
            await client.run()
            sent = [payload for payload in writer.payloads
                    if payload[2] == c.S_KEEPALIVE]
            self.assertGreaterEqual(len(sent), 2)
            # Each with a fresh id.
            ids = [int.from_bytes(payload[3:7], "big") for payload in sent]
            self.assertEqual(ids, sorted(set(ids)))
            # The read loop ended: the keepalive task went with it.
            await asyncio.sleep(0.05)
            count = len(writer.payloads)
            await asyncio.sleep(0.05)
            self.assertEqual(len(writer.payloads), count)
            self.assertEqual(
                [task for task in asyncio.all_tasks()
                 if task is not asyncio.current_task()], [])
            # The echo is recorded with its round trip, and not answered.
            client.writer = writer
            writer.payloads.clear()
            client._keepalive_sent = {ids[-1]: time.monotonic() - 0.25}
            echo = Packet(0).u32(ids[-1])
            await client._handle_keepalive(
                Cursor(bytes(echo.data)), bytes(echo.data))
            self.assertEqual(writer.payloads, [])
            self.assertGreaterEqual(client.keepalive_latency, 0.25)
            self.assertGreater(client._last_keepalive, 0.0)
            self.assertEqual(client._keepalive_sent, {})

        asyncio.run(run())

    def test_a_failing_keepalive_never_hides_the_read_loops_error(self):
        async def run():
            client = AtrinikClient(ClientConfig(reconnect=False))
            client.KEEPALIVE_SECONDS = (0.0, 0.0)
            ended = []

            class Writer:
                def close(self):
                    pass

                async def wait_closed(self):
                    pass

            async def connect():
                client.writer = Writer()
                client.state.phase = "playing"

            async def keepalive():
                raise RuntimeError("bug")

            async def read_loop():
                await asyncio.sleep(0.05)
                raise ConnectionError("dropped")

            async def emit(event, *args):
                ended.append(event)

            client.connect = connect
            client.send_keepalive = keepalive
            client._read_loop = read_loop
            client.emit = emit
            await client.run()
            self.assertIn("disconnected", ended)

        asyncio.run(run())

    def test_no_keepalive_before_she_plays(self):
        async def run():
            client = AtrinikClient(ClientConfig())
            client.KEEPALIVE_SECONDS = (0.01, 0.01)
            sent = []

            async def send(packet):
                sent.append(packet)

            client.send = send
            client.writer = object()
            client.state.phase = "character_login"
            loop = asyncio.create_task(client._keepalive_loop())
            await asyncio.sleep(0.05)
            self.assertEqual(sent, [])
            client.state.phase = "playing"
            await asyncio.sleep(0.05)
            loop.cancel()
            with self.assertRaises(asyncio.CancelledError):
                await loop
            self.assertTrue(sent)

        asyncio.run(run())

