    def test_engine_waits_for_the_first_map_after_a_reconnect(self):
        from .tasks import BotTask

        async def scenario():
            client = AtrinikClient(ClientConfig())
            engine = TaskEngine(client, tick_rate=0.01)
            ticks = []

            class Probe(BotTask):
                async def tick(self, client):
                    # Without a connection this send raises ConnectionError,
                    # which would permanently fail the task.
                    await client.talk("hello", "sage")
                    ticks.append(client.state.map.path)

            probe = Probe("probe")
            engine.set_task(probe)
            engine.running = True
            runner = asyncio.create_task(engine.run())
            # The whole reconnect holds the task: disconnected, connecting
            # (even with a stale map), then playing before the first MAP2.
            for phase, path in (("disconnected", ""), ("connecting", "/stale"),
                                ("playing", "")):
                client.state.phase = phase
                client.state.map.path = path
                await asyncio.sleep(0.05)
                self.assertEqual(ticks, [], phase)
                self.assertIs(engine.task, probe, phase)
            sent = []

            async def send(packet):
                sent.append(packet)

            client.send = send
            client.state.map.path = "/shattered_islands/world_14_77"
            await asyncio.sleep(0.05)
            engine.running = False
            await runner
            self.assertTrue(ticks)
            self.assertEqual(set(ticks), {"/shattered_islands/world_14_77"})

        asyncio.run(scenario())

    def test_engine_keeps_the_task_when_the_connection_drops_mid_tick(self):
        from .tasks import BotTask

        async def scenario():
            client = AtrinikClient(ClientConfig())
            client.state.phase = "playing"
            client.state.map.path = "/shattered_islands/world_14_77"
            engine = TaskEngine(client, tick_rate=0.01)
            ticks = []

            class Probe(BotTask):
                survives_disconnect = True

                async def tick(self, client):
                    ticks.append(client.state.phase)
                    # Not connected: the send raises ConnectionError.
                    await client.clear_actions()

            probe = Probe("probe")
            engine.set_task(probe)
            engine.running = True
            runner = asyncio.create_task(engine.run())
            await asyncio.sleep(0.05)
            self.assertTrue(ticks)
            self.assertIs(engine.task, probe)
            self.assertNotEqual(probe.status, TaskStatus.FAILED)
            # After the reconnect the same task carries on.
            sent = []

            async def send(packet):
                sent.append(packet)

            client.send = send
            await asyncio.sleep(0.05)
            engine.running = False
            await runner
            self.assertIs(engine.task, probe)
            self.assertTrue(sent)

            # A task that cannot rebuild its in-flight work still fails.
            class Plain(BotTask):
                async def tick(self, client):
                    await client.clear_actions()

            client.send = AtrinikClient.send.__get__(client)
            plain = Plain("plain")
            engine.set_task(plain)
            engine.running = True
            runner = asyncio.create_task(engine.run())
            await asyncio.sleep(0.05)
            engine.running = False
            await runner
            self.assertIsNone(engine.task)
            self.assertEqual(plain.status, TaskStatus.FAILED)

        asyncio.run(scenario())

    def playing_engine(self):
        client = AtrinikClient(ClientConfig())
        client.state.phase = "playing"
        client.state.map.path = "/shattered_islands/world_14_77"
        sent = []

        async def send(packet):
            sent.append(packet)

        client.send = send
        engine = TaskEngine(client, tick_rate=0.001)
        engine.error_backoff = 0.001
        return client, engine, sent

    @staticmethod
    async def until(condition, timeout=2.0):
        """Wait for ``condition()`` (not a fixed sleep); fail on timeout."""
        async def poll():
            while not condition():
                await asyncio.sleep(0.001)
        await asyncio.wait_for(poll(), timeout)

    @staticmethod
    def clears(sent):
        return [i for i, packet in enumerate(sent)
                if isinstance(packet, Packet) and packet.packet_type == c.S_CLEAR]

    def test_stop_while_the_engine_awaits_a_tick_does_not_raise(self):
        # Live 2026-11-18: Stop shortly after start-up set engine.task to
        # None while autoplay's tick awaited, and the status check after the
        # await raised AttributeError, which ended the whole process.
        from .web_server import WebControlServer

        async def scenario():
            client, engine, sent = self.playing_engine()
            server = WebControlServer(client, engine, WorldGraph())
            entered, release, finished = (asyncio.Event(), asyncio.Event(),
                                          asyncio.Event())

            class Slow(BotTask):
                raise_after = False

                async def tick(self, client):
                    entered.set()
                    await release.wait()
                    # The rest of a stale tick still sends.
                    await client.send("stale-move")
                    finished.set()
                    if self.raise_after:
                        raise RuntimeError("child failed after the stop")

            runner = asyncio.create_task(engine.run())
            for raise_after in (False, True):
                for event in (entered, release, finished):
                    event.clear()
                slow = Slow("slow")
                slow.raise_after = raise_after
                slow.status = TaskStatus.RUNNING
                engine.set_task(slow)
                await asyncio.wait_for(entered.wait(), 2)
                self.assertEqual(await server._set_task({"type": "stop"}),
                                 {"ok": True, "task": None})
                del sent[:]
                release.set()
                await asyncio.wait_for(finished.wait(), 2)
                # The stale send is cleared again afterwards.
                await self.until(lambda: self.clears(sent) and
                                 self.clears(sent)[-1] > sent.index("stale-move"))
                self.assertFalse(runner.done())
                self.assertIsNone(engine.task)
                # The operator's reason survives what the tick did after.
                self.assertEqual((slow.status, slow.error),
                                 (TaskStatus.FAILED, "stopped by operator"))
                self.assertTrue(engine.last_task["error"].startswith(
                    "stopped by operator"))

            # Replacement mid-tick keeps the new task and ticks it.
            for event in (entered, release, finished):
                event.clear()
            old = Slow("old")
            old.status = TaskStatus.RUNNING
            engine.set_task(old)
            await asyncio.wait_for(entered.wait(), 2)

            class Done(BotTask):
                async def tick(self, client):
                    self.status = TaskStatus.COMPLETE

            new = Done("new")
            await server._replace_task(new)
            release.set()
            await self.until(lambda: new.status == TaskStatus.COMPLETE
                             and engine.task is None)
            engine.running = False
            await runner
            self.assertEqual((old.status, old.error),
                             (TaskStatus.FAILED, "replaced by operator"))
            self.assertEqual(engine.last_task["name"], "new")

        asyncio.run(scenario())

    def test_an_exception_in_a_tick_fails_only_that_task(self):
        async def scenario():
            client, engine, _ = self.playing_engine()

            class Broken(BotTask):
                async def tick(self, client):
                    raise RuntimeError("bug in a tick")

            broken = Broken("broken")
            engine.set_task(broken)
            runner = asyncio.create_task(engine.run())
            await self.until(lambda: engine.task is None)
            self.assertFalse(runner.done())
            self.assertEqual((broken.status, broken.error),
                             (TaskStatus.FAILED, "bug in a tick"))

            # A bookkeeping error after a tick ends that task (it is cleared
            # first) and the next one still runs.
            class Ends(BotTask):
                async def tick(self, client):
                    self.status = TaskStatus.COMPLETE

            recorded = []

            def record_action(action, detail=""):
                recorded.append(action)
                if action == "task-end" and len(recorded) == 2:
                    raise RuntimeError("bug in the recorder")

            client.record_action = record_action
            first = Ends("first")
            engine.set_task(first)
            await self.until(lambda: len(recorded) >= 2)
            await self.until(lambda: engine.task is None)
            second = Ends("second")
            engine.set_task(second)
            await self.until(lambda: engine.last_task["name"] == "second")
            self.assertIsNone(engine.task)
            self.assertFalse(runner.done())
            engine.running = False
            await runner

        asyncio.run(scenario())

    def test_a_repeated_upkeep_error_backs_off_and_keeps_the_task(self):
        async def scenario():
            client, engine, _ = self.playing_engine()
            engine.error_backoff, engine.error_backoff_max = 0.001, 0.004
            engine.tick_rate = 0.0001
            ticks, sleeps = [], []

            class Steady(BotTask):
                async def tick(self, client):
                    ticks.append(1)

            steady = Steady("steady")
            steady.status = TaskStatus.RUNNING
            engine.set_task(steady)
            failing = [True]

            async def normalize():
                if failing[0]:
                    raise RuntimeError("bug in upkeep")
                return False

            engine._normalize_inventory_locks = normalize
            real_sleep = asyncio.sleep

            async def sleep(delay, *args):
                sleeps.append(delay)
                await real_sleep(0)

            with patch.object(asyncio, "sleep", sleep), \
                    self.assertLogs(TaskEngine.__module__, "ERROR") as logs:
                runner = asyncio.create_task(engine.run())
                while len(sleeps) < 6:
                    await real_sleep(0)
                # The task is kept, never failed or ticked meanwhile.
                self.assertIs(engine.task, steady)
                self.assertEqual(steady.status, TaskStatus.RUNNING)
                self.assertEqual(ticks, [])
                # Exponential, capped.
                self.assertEqual(sleeps[:6], [0.001, 0.002, 0.004, 0.004,
                                              0.004, 0.004])
                # One traceback for the repeated identical error.
                self.assertEqual(len(logs.records), 1)
                self.assertIsNotNone(logs.records[0].exc_info)
                # A clean step resets the backoff and the task ticks again.
                failing[0] = False
                while not ticks:
                    await real_sleep(0)
                self.assertIn(engine.tick_rate, sleeps)
                count = len(sleeps)
                failing[0] = True

                def backoffs():
                    return [delay for delay in sleeps[count:]
                            if delay != engine.tick_rate]

                while len(backoffs()) < 2:
                    await real_sleep(0)
                self.assertEqual(backoffs()[:2], [0.001, 0.002])
                engine.running = False
                await runner
            self.assertIs(engine.task, steady)

        asyncio.run(scenario())

    def test_a_repeated_engine_error_is_counted_at_most_once_a_minute(self):
        client, engine, _ = self.playing_engine()
        error = RuntimeError("same bug")
        clock = [1000.0]
        with patch.object(time, "monotonic", lambda: clock[0]), \
                self.assertLogs(TaskEngine.__module__, "ERROR") as logs:
            for _ in range(5):
                engine._report_step_error(error)
            clock[0] += 61
            engine._report_step_error(error)
            engine._report_step_error(RuntimeError("another bug"))
        messages = [record.getMessage() for record in logs.records]
        self.assertEqual(messages, [
            "task engine step failed",
            "task engine step failed 5 more times: RuntimeError: same bug",
            "task engine step failed"])

    def test_pending_engine_error_repeats_are_flushed(self):
        _, engine, _ = self.playing_engine()
        with self.assertLogs(TaskEngine.__module__, "ERROR") as logs:
            for _ in range(3):
                engine._step_failed(RuntimeError("first bug"))
            # A different error reports the first one's repeats first.
            for _ in range(2):
                engine._step_failed(KeyError("second bug"))
            # So does a clean step.
            engine._step_succeeded()
            # And the same error afterwards is reported in full again.
            engine._step_failed(KeyError("second bug"))
        self.assertEqual([record.getMessage() for record in logs.records], [
            "task engine step failed",
            "task engine step failed 2 more times: RuntimeError: first bug",
            "task engine step failed",
            "task engine step failed 1 more times: KeyError: 'second bug'",
            "task engine step failed"])
        self.assertEqual((engine.step_error, engine.step_error_count),
                         ("KeyError: 'second bug'", 1))

    def test_a_failing_engine_step_is_shown_and_alerted_until_clean(self):
        from .alerts import ENGINE_ERROR_CRITICAL_SECONDS, ENGINE_ERROR_STEPS
        from .web_server import WebControlServer

        async def scenario():
            client, engine, _ = self.playing_engine()
            engine.error_backoff_max = 0.001
            server = WebControlServer(client, engine, WorldGraph())
            failing = [True]

            async def normalize():
                if failing[0]:
                    raise RuntimeError("bug in upkeep")
                return False

            engine._normalize_inventory_locks = normalize

            def engine_alerts():
                return [alert for alert in server.dashboard.alerts()
                        if alert["id"] == "engine-error"]

            with self.assertLogs(TaskEngine.__module__, "ERROR"):
                runner = asyncio.create_task(engine.run())
                await self.until(lambda: engine.step_error_count >= 1)
                started = engine.step_error_since
                self.assertLessEqual(abs(started - time.time()), 5)
                snapshot = server.dashboard.snapshot()
                self.assertEqual(snapshot["engine_error"]["error"],
                                 "RuntimeError: bug in upkeep")
                await self.until(
                    lambda: engine.step_error_count > ENGINE_ERROR_STEPS)
                self.assertEqual(engine.step_error_since, started)
                self.assertEqual([alert["level"] for alert in engine_alerts()],
                                 ["warn"])
                # Ten minutes of it is critical.
                engine.step_error_since = (time.time()
                                           - ENGINE_ERROR_CRITICAL_SECONDS - 1)
                alerts = engine_alerts()
                self.assertEqual(alerts[0]["level"], "critical")
                self.assertIn("bug in upkeep", alerts[0]["text"])
                # A clean step clears both.
                failing[0] = False
                await self.until(lambda: engine.step_error_count == 0)
            self.assertIsNone(server.dashboard.snapshot()["engine_error"])
            self.assertEqual(engine_alerts(), [])
            engine.running = False
            await runner

        asyncio.run(scenario())

    def test_a_connection_error_or_disconnect_does_not_clear_an_engine_error(self):
        async def scenario():
            client, engine, _ = self.playing_engine()
            engine.error_backoff_max = 0.001
            mode = ["fail"]

            async def normalize():
                if mode[0] == "fail":
                    raise RuntimeError("bug in upkeep " + "x" * 400)
                if mode[0] == "drop":
                    raise ConnectionError("closed")
                return False

            engine._normalize_inventory_locks = normalize
            with self.assertLogs(TaskEngine.__module__, "WARNING"):
                runner = asyncio.create_task(engine.run())
                await self.until(lambda: engine.step_error_count >= 3)
                self.assertLessEqual(len(engine.step_error), 200)
                count, since = engine.step_error_count, engine.step_error_since
                mode[0] = "drop"
                await asyncio.sleep(0.05)
                self.assertGreaterEqual(engine.step_error_count, count)
                self.assertEqual(engine.step_error_since, since)
                mode[0] = "clean"
                client.state.phase = "connecting"
                await asyncio.sleep(0.05)
                self.assertGreaterEqual(engine.step_error_count, count)
                client.state.phase = "playing"
                await self.until(lambda: engine.step_error_count == 0)
            engine.running = False
            await runner

        asyncio.run(scenario())

    def test_engine_error_alert_needs_more_than_a_few_failed_steps(self):
        from .alerts import (ENGINE_ERROR_CRITICAL_SECONDS, ENGINE_ERROR_STEPS,
                             ProgressWatch, active)

        now = 10_000.0
        state = GameState()
        watch = ProgressWatch(now)

        def levels(count, since):
            return [alert["level"] for alert in active(
                state, [], watch, autoplay_started_at=None, now=now,
                engine_error={"error": "RuntimeError: x", "count": count,
                              "since": since})
                    if alert["id"] == "engine-error"]

        self.assertEqual(levels(ENGINE_ERROR_STEPS, now - 3600), [])
        self.assertEqual(levels(ENGINE_ERROR_STEPS + 1, now - 60), ["warn"])
        self.assertEqual(levels(ENGINE_ERROR_STEPS + 1,
                                now - ENGINE_ERROR_CRITICAL_SECONDS),
                         ["critical"])

    def test_stop_during_an_idle_food_trip_tick_is_not_a_failed_trip(self):
        from .autoplay import IdleSurvival

        async def scenario():
            client, _, sent = self.playing_engine()
            survival = IdleSurvival(WorldGraph())
            entered, release = asyncio.Event(), asyncio.Event()

            class Trip(BotTask):
                async def tick(self, client):
                    entered.set()
                    await release.wait()
                    await client.send("stale-step")
                    self.fail("route ended by the stop")

            trip = Trip("temple food")
            survival.child = trip
            ticking = asyncio.create_task(survival.tick(client))
            await asyncio.wait_for(entered.wait(), 2)
            survival.hold(client, "stopped by operator")
            release.set()
            self.assertFalse(await ticking)
            self.assertIsNone(survival.child)
            # No failure backoff: the operator ended it, not the route.
            self.assertEqual((survival._failures, survival._retry_at), (0, 0.0))
            # And the stale step is cleared, so she does not keep walking.
            self.assertGreater(self.clears(sent)[-1], sent.index("stale-step"))

        asyncio.run(scenario())

