        node.terrain = {(x, y): 1 for x in range(25) for y in range(25)}
        node.blocked.add((1, 0))
        task = FarmTask(zone="/test", target="lost soul")
        task.map_node = node
        self.assertFalse(task.target_tile_walkable(client, 9, 8))
        asyncio.run(task.tick(client))
