    # world_16_74's aggressive residents (spawns.txt): eight charred
    # treants, a singed bear and a singed deer, each acquiring her within 3.
    WORLD_16_74_SPAWNS = [
        (0, 9, 3), (4, 3, 3), (6, 12, 3), (8, 19, 3), (13, 3, 3),
        (14, 9, 3), (14, 16, 3), (19, 4, 3), (20, 13, 3), (22, 19, 3)]

    def test_farm_retreat_backs_out_along_the_trail_clear_of_other_spawns(self):
        # Live on world_16_74 (2026-11-25) her retreat from one or two
        # treants ran past the other spawns: the pack grew from 2 to 8 in
        # 23 s and she ran a loop around the whole map. Engaged by the
        # (4, 3) treant at (6, 7), she backs out along the cleared trail she
        # came in on (y 7 from the east), then keeps clear of every other
        # spawn's radius.
        from . import tasks as tasks_module

        client = self._combat_client()
        client.state.map.tiles.clear()
        client.state.stats.update(hp=30, maxhp=100, sp=0)
        self._record_actions(client)
        task = FarmTask(zone="/test", target="charred treant")
        task.resident_spawns = list(self.WORLD_16_74_SPAWNS)
        node = MapNode(path="/test", width=24, height=24)
        node.terrain = {(x, y): 1 for x in range(24) for y in range(24)}
        task.map_node = node
        task.map_bounds = (24, 24)
        now = time.monotonic()
        task._cleared_trail = {
            ("/test", x, 7): now for x in (10, 9, 8, 7, 6)}
        position = (6, 7)
        treant = MapObject(
            3, 1, 0, 0, name="charred treant", target_id=100, target_hp=80)
        behind = (5, 6)
        steps = []
        with patch.object(tasks_module.random, "random", return_value=0.5):
            for _ in range(6):
                m = client.state.map
                m.world_x, m.world_y = position
                m.tiles.clear()
                m.tile(8 + behind[0] - position[0],
                       8 + behind[1] - position[1]).objects[3] = treant
                client.state.messages = [(
                    time.time(), 2, "ff0000",
                    "charred treant hit you for 25 (-20) impact damage.")]
                task.remember_engagement(
                    client, 8 + behind[0] - position[0],
                    8 + behind[1] - position[1], 100)
                task._last_retreat_step_at = 0.0
                client.direct_moves.clear()
                self.assertTrue(asyncio.run(task.low_health_retreat(client)))
                self.assertEqual(len(client.direct_moves), 1)
                dx, dy = c.DIRECTION_DELTAS[client.direct_moves[0][0]]
                # The treant follows onto the square she left.
                behind, position = position, (
                    position[0] + dx, position[1] + dy)
                steps.append(position)
        self.assertEqual(steps[:4], [(7, 7), (8, 7), (9, 7), (10, 7)])
        for x, y in steps:
            for spawn_x, spawn_y, radius in self.WORLD_16_74_SPAWNS:
                if (spawn_x, spawn_y) == (4, 3):
                    continue
                self.assertGreater(
                    max(abs(x - spawn_x), abs(y - spawn_y)), radius,
                    (steps, (spawn_x, spawn_y)))
        self.assertIn("trail=1", next(
            detail for action, detail in client.recorded
            if action == "retreat-choice"))

    def test_farm_retreat_keeps_clear_of_a_visible_idle_hostile(self):
        # A hostile in view but not in the fight wakes within its detection
        # radius: of two otherwise equal steps she takes the one that
        # stays out of it.
        from . import tasks as tasks_module

        client = self._combat_client()
        client.state.map.tiles.clear()
        client.state.stats.update(hp=30, maxhp=100, sp=0)
        self._record_actions(client)
        task = FarmTask(zone="/test", target="charred treant",
                        aggressive_detection_ranges={"charred treant": 3})
        node = MapNode(path="/test", width=24, height=24)
        node.terrain = {(x, y): 1 for x in range(24) for y in range(24)}
        task.map_node = node
        task.map_bounds = (24, 24)
        client.state.map.world_x = client.state.map.world_y = 12
        # The engaged one to her west; an idle one four tiles east and
        # three south of her.
        client.state.map.tile(7, 8).objects[3] = MapObject(
            3, 1, 0, 0, name="charred treant", target_id=100, target_hp=80)
        client.state.map.tile(12, 11).objects[3] = MapObject(
            3, 2, 0, 0, name="charred treant", target_id=101, target_hp=100)
        task.remember_engagement(client, 7, 8, 100)
        client.state.messages = [(
            time.time(), 2, "ff0000",
            "charred treant hit you for 25 (-20) impact damage.")]
        with patch.object(tasks_module.random, "random", return_value=0.5):
            self.assertTrue(asyncio.run(task.low_health_retreat(client)))
        dx, dy = c.DIRECTION_DELTAS[client.direct_moves[0][0]]
        # Every step east keeps two tiles from the engaged treant and has
        # the most room; only the north-east one stays out of the idle
        # one's radius.
        self.assertEqual((dx, dy), (1, -1))

    def test_farm_retreat_gets_clear_before_avoiding_a_spawn(self):
        # When every way clear of the attacker enters a spawn's radius,
        # she still gets clear: a hazard-free step that stays beside it
        # and leads nowhere clear only circles it with combat off. Here a
        # corridor three squares wide runs east into the spawn's radius.
        from . import tasks as tasks_module

        client = self._combat_client()
        client.state.map.tiles.clear()
        client.state.stats.update(hp=30, maxhp=100, sp=0)
        self._record_actions(client)
        task = FarmTask(zone="/test", target="charred treant")
        task.resident_spawns = [(16, 12, 3)]
        node = MapNode(path="/test", width=24, height=24)
        node.terrain = {(x, y): (1 if 11 <= y <= 13 else 0)
                        for x in range(24) for y in range(24)}
        task.map_node = node
        task.map_bounds = (24, 24)
        client.state.map.world_x = client.state.map.world_y = 12
        client.state.map.tile(7, 8).objects[3] = MapObject(
            3, 1, 0, 0, name="charred treant", target_id=100, target_hp=80)
        task.remember_engagement(client, 7, 8, 100)
        client.state.messages = [(
            time.time(), 2, "ff0000",
            "charred treant hit you for 25 (-20) impact damage.")]
        with patch.object(tasks_module.random, "random", return_value=0.5):
            self.assertTrue(asyncio.run(task.low_health_retreat(client)))
        dx, _ = c.DIRECTION_DELTAS[client.direct_moves[0][0]]
        self.assertEqual(dx, 1)
        self.assertIn("hazards=1", next(
            detail for action, detail in client.recorded
            if action == "retreat-choice"))

        # A spawn whose radius she stood in lately, with nothing on her,
        # is empty or asleep: no hazard.
        task._cleared_trail[("/test", 13, 12)] = time.monotonic()
        self.assertEqual(task.retreat_hazards(client, {100}), [(12, 8, 3)])
        client.state.map.tile(12, 8)  # its square now in view, empty
        self.assertEqual(task.retreat_hazards(client, {100}), [])

    def _outpaced_client(self, *targets, hp=320):
        """Her at world (12, 12) on an open 25x25 farm map, 356 maximum
        health, heals outpaced (_outpaced_messages), with the given
        (view x, view y, name, target id, target HP %) attackers."""
        client = self._combat_client()
        client.state.map.tiles.clear()
        for x, y, name, target_id, target_hp in targets:
            client.state.map.tile(x, y).objects[3] = MapObject(
                3, target_id, 0, 0, name=name, target_id=target_id,
                target_hp=target_hp)
        client.state.stats.update(hp=hp, maxhp=356, sp=60, maxsp=71,
                                  weapon_speed=2.0)
        client.state.inventory.append(Item(
            43, item_type=c.TYPE_SPELL, name="minor healing",
            extra={"cost": 4}))
        client.state.messages = self._outpaced_messages()
        client.fired = []

        async def fire(direction, tag=0):
            client.fired.append((direction, tag))

        client.fire = fire
        self._record_actions(client)
        client.state.map.world_x = client.state.map.world_y = 12
        return client

    def _outpaced_task(self, target="charred treant"):
        task = FarmTask(zone="/test", target=target,
                        safety=SafetyPolicy(heal_below=0.95, flee_below=0.80))
        node = MapNode(path="/test", width=25, height=25)
        node.terrain = {(x, y): 1 for x in range(25) for y in range(25)}
        task.map_node = node
        task.map_bounds = (25, 25)
        return task

    def test_two_treants_outpacing_heals_disengage_along_the_trail(self):
        # Two treants beside her out-damage her heals at 90%: she
        # disengages as before (healing-outpaced), but back along the
        # cleared trail she came in on rather than anywhere.
        from . import tasks as tasks_module

        client = self._outpaced_client(
            (7, 8, "charred treant", 100, 100),
            (7, 9, "charred treant", 101, 100))
        task = self._outpaced_task()
        task.remember_engagement(client, 7, 8, 100)
        now = time.monotonic()
        # East, north-east and south-east all get two tiles clear of both;
        # the trail runs north-east.
        task._cleared_trail = {("/test", 13, 11): now, ("/test", 14, 10): now}
        with patch.object(tasks_module.random, "random", return_value=0.5):
            asyncio.run(task.tick(client))
        self.assertIn("healing-outpaced",
                      [action for action, _ in client.recorded])
        self.assertEqual(client.direct_moves, [(2, False)])
        self.assertNotIn(True, client.combat)

    def test_seam_retreat_under_contact_keeps_combat_and_target(self):
        # Live at 16:15 a farm retreat stepped across the seam onto
        # world_17_74; the walk's defence there held fire because that map
        # was not the destination: combat off and target cleared with three
        # attackers on her. Under contact after such a step she fights on.
        client = self._combat_client()
        client.state.map.tiles.clear()
        client.state.map.world_x = 10
        client.state.map.world_y = 10
        engaged = MapObject(
            3, 1, 0, 0, name="charred treant", target_id=100, target_hp=55)
        other = MapObject(
            3, 2, 0, 0, name="singed bear", target_id=101, target_hp=100)
        client.state.map.tile(9, 8).objects[3] = engaged
        client.state.map.tile(8, 9).objects[3] = other
        client.state.stats.update(hp=300, maxhp=356, sp=60, maxsp=71)
        client.state.target_id = engaged.target_id
        client.state.combat = True
        now = time.time()
        client.state.messages = [
            (now - 1.0, 2, "ff0000",
             "charred treant hit you for 25 (-20) impact damage."),
            (now - 0.5, 2, "ff0000",
             "singed bear hit you for 22 (-21) cleave damage.")]
        self._record_actions(client)
        transit = MapNode(path="/test", width=25, height=25)
        transit.terrain = {(x, y): 1 for x in range(25) for y in range(25)}
        graph = WorldGraph()
        graph.nodes = {"/test": transit,
                       "/farm": MapNode(path="/farm", width=24, height=24)}
        farm = FarmTask(zone="/farm", target="charred treant")
        farm.remember_engagement(client, 9, 8, engaged.target_id)
        farm._seam_step_at = time.monotonic() - 1.0
        task = NavigateThenTask(
            graph, "/farm", farm, combat_approach=True, safety=farm.safety)
        task._last_pull_target = engaged.target_id
        task._last_moved_at = time.monotonic()

        self.assertTrue(asyncio.run(task._defend_while_navigating(client)))
        actions = [action for action, _ in client.recorded]
        self.assertNotIn("navigation-transit-hold-fire", actions)
        self.assertIsNotNone(farm._engaged_target)
        self.assertEqual(farm._engaged_target[0], engaged.target_id)
        self.assertEqual(client.cleared_targets, 0)
        self.assertEqual(client.combat[-1], True)
        self.assertIn((9, 8, engaged.target_id), client.targets)
        self.assertEqual(client.direct_moves, [])

        # With the committed target two tiles off, she fights the one
        # beside her rather than walking to it.
        client.state.map.tiles.clear()
        client.state.map.tile(10, 8).objects[3] = engaged
        client.state.map.tile(8, 9).objects[3] = other
        task._last_defense_action = 0.0
        self.assertTrue(asyncio.run(task._defend_while_navigating(client)))
        self.assertEqual(client.targets[-1], (8, 9, other.target_id))
        self.assertEqual(client.direct_moves, [])
        client.state.map.tiles.clear()
        client.state.map.tile(9, 8).objects[3] = engaged
        client.state.map.tile(8, 9).objects[3] = other

        # The walk's own tick, back on its way off the farm map, sends no
        # combat off either.
        task.navigation.status = TaskStatus.COMPLETE
        client.combat.clear()
        asyncio.run(task.tick(client))
        self.assertNotIn(False, client.combat)

        # Contact that goes on holds it past the start window, but not
        # past the cap; a seam step long ago with no latch starts nothing.
        farm._seam_step_at = time.monotonic() - 60.0
        self.assertTrue(task._seam_retreat_contact(client))
        farm._seam_step_at = (
            time.monotonic() - task.SEAM_RETREAT_FIGHT_CAP_SECONDS - 1)
        self.assertFalse(task._seam_retreat_contact(client))
        farm._seam_step_at = time.monotonic() - 60.0
        self.assertFalse(task._seam_retreat_contact(client))
        # Nor does it override a care crossing's hold-fire.
        farm._seam_step_at = time.monotonic() - 1.0
        task.navigation.care_holds_fire = lambda path: True
        client.recorded.clear()
        asyncio.run(task._defend_while_navigating(client))
        self.assertIn("navigation-transit-hold-fire",
                      [action for action, _ in client.recorded])

    def test_seam_fight_below_the_pack_flee_line_steps_away_or_fights(self):
        # Under contact after the farm retreat's seam step, below the
        # farm's own pack flee line (80% with two near), she does what the
        # farm's retreat does: a step that gains distance, combat off; with
        # none she is cornered and fights the attacker beside her.
        def setup(walkable):
            client = self._combat_client()
            client.state.map.tiles.clear()
            client.state.map.world_x = client.state.map.world_y = 10
            engaged = MapObject(
                3, 1, 0, 0, name="charred treant", target_id=100,
                target_hp=55)
            other = MapObject(
                3, 2, 0, 0, name="singed bear", target_id=101,
                target_hp=40)
            client.state.map.tile(9, 8).objects[3] = engaged
            client.state.map.tile(8, 9).objects[3] = other
            client.state.stats.update(hp=130, maxhp=356, sp=60, maxsp=71)
            client.state.inventory.append(Item(
                43, item_type=c.TYPE_SPELL, name="minor healing",
                extra={"cost": 4}))
            client.state.target_id = engaged.target_id
            client.state.combat = True
            now = time.time()
            client.state.messages = [
                (now - 1.0, 2, "ff0000",
                 "charred treant hit you for 25 (-20) impact damage."),
                (now - 0.5, 2, "ff0000",
                 "singed bear hit you for 22 (-21) cleave damage.")]
            self._record_actions(client)
            transit = MapNode(path="/test", width=25, height=25)
            transit.terrain = {
                (x, y): 1 for x in range(25) for y in range(25)
                if walkable(x, y)}
            graph = WorldGraph()
            graph.nodes = {"/test": transit,
                           "/farm": MapNode(path="/farm", width=24,
                                            height=24)}
            farm = FarmTask(zone="/farm", target="charred treant",
                            safety=SafetyPolicy(heal_below=0.95,
                                                flee_below=0.60))
            farm.remember_engagement(client, 9, 8, engaged.target_id)
            farm._seam_step_at = time.monotonic() - 1.0
            task = NavigateThenTask(
                graph, "/farm", farm, combat_approach=True,
                safety=farm.safety)
            task._last_pull_target = engaged.target_id
            task._last_moved_at = time.monotonic()
            # Between heals: the last one just went out.
            farm.safety._last_heal = time.monotonic()
            return client, task, farm

        # Open ground: a step that gains distance, combat off.
        client, task, farm = setup(lambda x, y: True)
        self.assertTrue(asyncio.run(task._defend_while_navigating(client)))
        self.assertEqual(len(client.direct_moves), 1)
        self.assertNotIn(True, client.combat)
        self.assertNotIn("navigation-transit-hold-fire",
                         [action for action, _ in client.recorded])

        # Walled in (only her square and the attackers'): cornered, she
        # fights her committed target beside her.
        client, task, farm = setup(
            lambda x, y: (x, y) in {(10, 10), (11, 10), (10, 11)})
        self.assertTrue(asyncio.run(task._defend_while_navigating(client)))
        self.assertEqual(client.direct_moves, [])
        self.assertEqual(client.combat[-1], True)
        self.assertEqual(client.targets[-1], (9, 8, 100))

    def test_seam_contact_with_the_pack_at_range_does_not_close_in(self):
        # Seam contact with nobody beside her but two treants three tiles
        # off: the seam fight does not apply, and the walk's pack handling
        # runs as on the farm's own map (avoid or split), rather than the
        # nearest-fight walking her into the pack.
        client = self._combat_client()
        client.state.map.tiles.clear()
        client.state.map.world_x = client.state.map.world_y = 10
