    def test_persistent_pack_at_exit_selects_an_alternate_route(self):
        client = self._combat_client()
        client.state.map.tiles.clear()
        client.state.map.tile(12, 8).objects[3] = MapObject(
            3, 1, 0, 0, name="ogre", target_id=100, target_hp=100)
        client.state.map.tile(13, 8).objects[3] = MapObject(
            3, 2, 0, 0, name="ettin", target_id=200, target_hp=100)
        node = MapNode(path="/test", width=25, height=25)
        node.terrain = {(x, y): 1 for x in range(25) for y in range(25)}
        graph = WorldGraph()
        graph.nodes = {"/test": node}
        # The well is one way to the farm; another exit is the alternate
        # (the last way on is never excluded).
        for path in ("/well", "/farm"):
            graph.nodes[path] = MapNode(path=path, width=3, height=3, terrain={
                (x, y): 1 for x in range(3) for y in range(3)})
        node.edges = [
            MapEdge("/test", "/well", 13, 22, 1, 1, kind="exit", label="stone well"),
            MapEdge("/test", "/farm", 1, 1, 1, 1, kind="exit")]
        graph.nodes["/well"].edges = [MapEdge("/well", "/farm", 0, 0, 1, 1, kind="exit")]
        task = NavigateThenTask(
            graph, "/farm", FarmTask(zone="/farm"),
            combat_approach=True)
        task.navigation.route = [MapEdge(
            "/test", "/well", 13, 22, kind="exit", label="stone well")]

        with patch("atrinik_bot.navigation.time.monotonic",
                   return_value=100.0):
            self.assertFalse(asyncio.run(
                task._defend_while_navigating(client)))
        # Normal NavigateThenTask.tick replans immediately after the first
        # avoidance pass. Recreate that same chosen exit for the focused
        # defense helper call.
        task.navigation.route = [MapEdge(
            "/test", "/well", 13, 22, kind="exit", label="stone well")]
        with patch("atrinik_bot.navigation.time.monotonic",
                   return_value=116.0):
            self.assertFalse(asyncio.run(
                task._defend_while_navigating(client)))

        # Excluded at the patched clock (it expires EDGE_EXCLUSION_SECONDS on).
        self.assertEqual(task.navigation._edge_exclusions, {
            ("/test", "/well", 13, 22):
                116.0 + NavigateTask.EDGE_EXCLUSION_SECONDS})
        self.assertEqual(task.navigation.route, [])

    def test_pack_split_retreat_forbids_immediate_backtrack(self):
        client = self._combat_client()
        client.state.map.world_x = 12
        client.state.map.world_y = 12
        node = MapNode(path="/test", width=25, height=25)
        node.terrain = {(x, y): 1 for x in range(25) for y in range(25)}
        graph = WorldGraph()
        graph.nodes = {"/test": node}
        task = NavigateThenTask(
            graph, "/shop", BuyGroundItemsTask(r"^staple food$", 5),
            combat_approach=True)
        calls = []

        async def retreat(client, threats, **kwargs):
            calls.append(kwargs)
            return True

        task._retreat_step = retreat
        client.state.messages = [(
            time.time(), 2, "cc66ff", "kobold chief hit you for 4 damage.")]
        self._corner(task, client)
        self.assertTrue(asyncio.run(task._defend_while_navigating(client)))
        # A probe (is there a step?) comes first; it sends nothing.
        self.assertEqual(calls, [{"avoid_backtrack": True, "gain_only": True,
                                  "probe": True},
                                 {"avoid_backtrack": True, "gain_only": True}])

    def _outpost_box(self, *, golem_level=0, giant_level=0, level=37):
        """Live shape (2026-11-24, the Old Outpost upper-middle room): she
        stands at (16, 6), walls on five sides, two stone giant master
        guards west and south-west, a lava golem south, and they hit her."""
        client = self._combat_client()
        client.state.map.tiles.clear()
        client.state.map.world_x, client.state.map.world_y = 16, 6
        client.state.stats.update(hp=330, maxhp=330, level=level)
        client.decisions = []
        client.record_action = lambda action, detail="": (
            client.decisions.append((action, detail)))
        for target_id, (wx, wy), name in (
                (801, (15, 6), "stone giant master guard"),
                (802, (15, 7), "stone giant master guard"),
                (803, (16, 7), "lava golem")):
            client.state.map.tile(8 + wx - 16, 8 + wy - 6).objects[3] = (
                MapObject(3, 1, 0, 0, name=name, target_id=target_id,
                          target_hp=100))
        node = MapNode(path="/outpost", width=24, height=24)
        node.terrain = {(x, y): 1 for x in range(24) for y in range(24)}
        for wall in ((15, 5), (16, 5), (17, 5), (17, 6), (17, 7)):
            node.blocked.add(wall)
        client.state.map.path = "/outpost"
        graph = WorldGraph()
        graph.nodes = {"/outpost": node,
                       "/pool": MapNode(path="/pool", width=24, height=24)}
        if giant_level:
            graph.monster_levels["stone giant master guard"] = giant_level
        if golem_level:
            graph.monster_levels["lava golem"] = golem_level
        task = NavigateThenTask(
            graph, "/pool", BuyGroundItemsTask(r"^staple food$", 5),
            combat_approach=True)
        task._trail = [("/outpost", 9, 9), ("/outpost", 16, 6)]
        return client, node, task

    def _hit(self, client, name="stone giant master guard"):
        client.state.messages = [(
            time.time(), 2, "cc66ff", f"{name} hit you for 9 damage.")]

    def test_cornered_pack_split_fights_instead_of_combat_off(self):
        """Boxed in with no retreat square, two of a pack beside her (of
        unknown level, so they count as a pack): she fights the attacker
        beside her rather than turning combat off every tick."""
        client, node, task = self._outpost_box()
        self.assertTrue(all(not node.walkable(16 + dx, 6 + dy)
                            for dx, dy in ((-1, -1), (0, -1), (1, -1),
                                           (1, 0), (1, 1))))
        for _ in range(4):
            self._hit(client)
            self._corner(task, client)
            task._last_defense_action = 0.0
            self.assertTrue(asyncio.run(
                task._defend_while_navigating(client)))
        self.assertEqual(client.direct_moves, [])
        self.assertNotIn(False, client.combat)
        self.assertEqual(client.combat[-1], True)
        fought = client.targets[-1][2]
        self.assertIn(fought, (801, 802, 803))
        self.assertEqual({target for _, _, target in client.targets},
                         {fought})
        self.assertEqual(
            [action for action, _ in client.decisions].count(
                "navigation-cornered-fight"), 1)

    def test_cornered_fight_holds_its_target_when_a_square_opens(self):
        """Once fighting cornered, a square opening beside her does not
        flip her back to a combat-off retreat while that attacker stays."""
        client, node, task = self._outpost_box()
        self._hit(client)
        self._corner(task, client)
        asyncio.run(task._defend_while_navigating(client))
        fought = client.targets[-1][2]
        node.blocked.discard((17, 6))
        self._hit(client)
        self._corner(task, client)
        task._last_defense_action = 0.0
        self.assertTrue(asyncio.run(task._defend_while_navigating(client)))
        self.assertEqual(client.direct_moves, [])
        self.assertNotIn(False, client.combat)
        self.assertEqual(client.targets[-1][2], fought)

    def test_cornered_fight_at_range_does_not_step_back_into_the_corner(self):
        """Cornered at a corridor's dead end with the pack two and three
        tiles off and hitting her: she closes on the nearest and goes on
        fighting it once her step has opened a retreat square behind her."""
        client, node, task = self._outpost_box()
        client.state.map.tiles.clear()
        client.state.map.world_x, client.state.map.world_y = 16, 3
        node.blocked.clear()
        node.terrain = {(16, y): 1 for y in range(3, 11)}
        for target_id, wy in ((801, 5), (802, 6)):
            client.state.map.tile(8, 8 + wy - 3).objects[3] = MapObject(
                3, 1, 0, 0, name="stone giant master guard",
                target_id=target_id, target_hp=100)
        task._trail = [("/outpost", 16, 4), ("/outpost", 16, 3)]
        self._hit(client)
        self._corner(task, client)
        self.assertTrue(asyncio.run(task._defend_while_navigating(client)))
        self.assertEqual(client.targets[-1][2], 801)
        self.assertEqual(client.combat, [True])
        # Her step toward it lands: (16, 3) behind her would now be a
        # retreat square, but she keeps fighting the one she chose.
        client.state.map.world_y = 4
        client.state.map.tiles.clear()
        for target_id, wy in ((801, 5), (802, 6)):
            client.state.map.tile(8, 8 + wy - 4).objects[3] = MapObject(
                3, 1, 0, 0, name="stone giant master guard",
                target_id=target_id, target_hp=100)
        task._combat_attempt = None
        self._hit(client)
        task._last_defense_action = 0.0
        self.assertTrue(asyncio.run(task._defend_while_navigating(client)))
        self.assertNotIn(False, client.combat)
        self.assertEqual(client.targets[-1][2], 801)
        self.assertEqual(client.direct_moves[1:], [])

