    def test_mana_crystal_upgrade_aborts_on_death_recall_or_overrun(self):
        for action in ("death", "emergency-recall"):
            client = self._gandyld_client()
            client.decision_history = [
                {"time": time.time() - 60, "action": "death"}]
            task = ManaCrystalUpgradeTask(built_graph())
            asyncio.run(task.tick(client))
            # An older death does not count.
            self.assertEqual(task.status, TaskStatus.RUNNING)
            client.decision_history.append(
                {"time": time.time() + 1, "action": action})
            asyncio.run(task.tick(client))
            self.assertEqual(task.status, TaskStatus.FAILED)
            self.assertIn(action, task.error)
        client = self._gandyld_client()
        task = ManaCrystalUpgradeTask(built_graph())
        asyncio.run(task.tick(client))
        task._started_at -= task.MAX_SECONDS + 1
        asyncio.run(task.tick(client))
        self.assertEqual(task.status, TaskStatus.FAILED)
        self.assertIn("30 minutes", task.error)

