    def test_hazards_that_together_cut_off_most_of_the_world_stay_cost_only(self):
        from . import navigation
        from .navigation import route_death_blocked_maps

        client, circuit_a, _ = self.underground_client()
        graph = built_graph()
        # Ten reachable maps; each death map alone cuts off three of them,
        # both together six: over half. The largest cut (ties by name) is
        # dropped to cost-only until the rest are under the share.
        world = {f"/m{index}" for index in range(10)}
        cut = {"/m0": {"/m0", "/m1", "/m2"}, "/m3": {"/m3", "/m4", "/m5"}}

        def reach(client, graph, origin, avoided, access, search, overdue=False):
            return frozenset(world - set().union(*(cut[map_path] for map_path in avoided)))

        client.state.farm_adaptations = {"x": {"kit_failures": [
            {"time": time.time(), "cause": "route", "kind": "death",
             "map": map_path, "map_damage": 50, "kit": {}} for map_path in cut]}}
        with patch.object(navigation, "_reachable_from", side_effect=reach):
            self.assertEqual(route_death_blocked_maps(client, graph),
                             frozenset(cut["/m3"]))
            with patch.object(navigation, "ROUTE_DEATH_CHOKEPOINT_SHARE", 0.2):
                self.assertEqual(route_death_blocked_maps(client, graph), frozenset())
            with patch.object(navigation, "ROUTE_DEATH_CHOKEPOINT_SHARE", 0.6):
                self.assertEqual(route_death_blocked_maps(client, graph),
                                 frozenset(cut["/m0"] | cut["/m3"]))
        # A small dead end beside a large-cut hazard: the large cut is
        # dropped first and the dead end stays blocked.
        world = {f"/m{index}" for index in range(20)}
        cut = {"/big": {"/big"} | {f"/m{index}" for index in range(8)},
               "/entrance": {"/entrance", "/m18", "/m19"}}
        world |= set(cut)
        client.state.farm_adaptations = {"x": {"kit_failures": [
            {"time": time.time(), "cause": "route", "kind": "death",
             "map": map_path, "map_damage": 50, "kit": {}} for map_path in cut]}}
        with patch.object(navigation, "_reachable_from", side_effect=reach):
            self.assertEqual(route_death_blocked_maps(client, graph),
                             frozenset(cut["/entrance"]))

    def test_the_circuit_leaves_a_spot_only_reachable_through_a_death_map(self):
        from . import navigation

        circuit_a = analyzer_spot("UC circuit A", [self.UC + "2_2"], ["drow L32"])
        client = self.client({"xp": [circuit_a]})
        client.state.map.path, (client.state.map.world_x,
                                client.state.map.world_y) = self.RESPAWN
        client.state.savebed_map, client.state.savebed_xy = self.RESPAWN
        circuit = self.circuit(client, circuit_a)
        self.route_death(client, circuit_a, self.UC + "0_0")
        farm = circuit.child.task
        # Still judging: she keeps the plan rather than stopping.
        with patch.object(navigation, "ROUTE_DEATH_SEARCH_INTERVAL_SECONDS", 3600.0):
            navigation._reach_search_after[0] = time.monotonic() + 3600.0
            self.assertFalse(circuit._upgrade_progression(client, farm))
            self.assertNotEqual(circuit.status, TaskStatus.COMPLETE)
        navigation._reach_search_after[0] = 0.0
        # Finishing a fight, she does not stop either.
        with patch.object(FarmCircuitTask, "_busy_finishing_fight_or_loot",
                          return_value=True):
            self.assertFalse(circuit._upgrade_progression(client, farm))
        self.assertNotEqual(circuit.status, TaskStatus.COMPLETE)
        # Judged, with no other spot ranked: she stops instead of walking back.
        self.assertTrue(circuit._upgrade_progression(client, farm))
        self.assertEqual(circuit.status, TaskStatus.COMPLETE)
        self.assertIn("farm-spots-exhausted",
                      [entry["action"] for entry in client.decision_history])

    def recall_client(self):
        trees = analyzer_spot("Trees", [self.TREES], ["evil treant L13"])
        client = self.client({"xp": [trees]})
        # Fleeing a pack on the road at 16 of 244 hit points, with a wand.
        client.state.map.path = self.UC + "0_0"
        client.state.savebed_map, client.state.savebed_xy = self.RESPAWN
        client.state.stats.update(hp=16, maxhp=244)
        client.state.map.tile(client.state.map.width // 2 + 1,
                              client.state.map.height // 2).objects[3] = MapObject(
            3, 1, 0, 0, name="brown cave pudding", target_id=100, target_hp=100)
        client.state.add_message(2, "ff0000",
                                 "brown cave pudding hit you for 40 (-40) acid damage.")
        wand = Item(77, item_type=c.TYPE_WAND, quality=80, condition=80,
                    name="pine wand of word of recall (lvl 17)")
        client.state.place_item(wand, client.state.player_tag)
        client.applied, client.fired = [], []

        async def apply(tag):
            client.applied.append(tag)

        async def fire(direction, tag=0):
            client.fired.append((direction, tag))

        async def idle(*args, **kwargs):
            pass

        client.apply, client.fire = apply, fire
        client.clear_actions = client.set_combat = idle
        return client, trees, wand

    def test_low_health_on_the_way_to_a_farm_fires_word_of_recall(self):
        client, trees, wand = self.recall_client()
        circuit = self.circuit(client, trees)
        farm = circuit.child.task
        self.assertTrue(asyncio.run(circuit._transit_emergency_recall(client, farm)))
        self.assertEqual((client.applied, client.fired), ([77], []))
        # The readied wand fires on a later transit tick, whatever her health.
        wand.flags |= c.ITEM_APPLIED
        client.state.stats["hp"] = 200
        self.assertTrue(asyncio.run(circuit._transit_emergency_recall(client, farm)))
        self.assertEqual(client.fired, [(0, 0)])
        # It counts once the server says the recall force is building.
        self.assertNotIn("emergency-recall",
                         [entry["action"] for entry in client.decision_history])
        client.state.add_message(
            0, "ffffff", "You feel a force starting to build up inside you.")
        self.assertFalse(asyncio.run(circuit._transit_emergency_recall(client, farm)))
        self.assertIn("emergency-recall",
                      [entry["action"] for entry in client.decision_history])
        # Healthy, or without hostile contact, the charge is kept.
        fresh = self.circuit(client, trees)
        self.assertFalse(asyncio.run(
            fresh._transit_emergency_recall(client, fresh.child.task)))
        client.state.stats["hp"] = 16
        saved = list(client.state.messages)
        client.state.messages.clear()
        self.assertFalse(asyncio.run(
            fresh._transit_emergency_recall(client, fresh.child.task)))
        self.assertEqual(client.fired, [(0, 0)])
        # The circuit's own transit tick asks it before healing or fleeing.
        client.state.messages.extend(saved)
        wand.flags &= ~c.ITEM_APPLIED
        fresh.status = TaskStatus.RUNNING
        async def unsynced(*args, **kwargs):
            return False

        fresh.server_clock.sync = unsynced
        for name in dir(fresh):
            if name.startswith("_needs_"):
                setattr(fresh, name, lambda *args, **kwargs: False)
        asyncio.run(fresh.tick(client))
        self.assertEqual(client.applied, [77, 77])

