    def test_a_spot_whose_every_resident_kind_is_out_of_league_is_left(self):
        """Live, on 2026-11-25: out-healed disengages marked the kinds of
        world_16_74 out of her league, and she stayed there with nothing
        she might pull until she was cornered."""
        spot = analyzer_spot("Burnt Forest", [self.BURNT_16_74],
                             ["charred treant L33"])
        trees = analyzer_spot("Trees", [self.TREES], ["evil treant L13"])
        client = self.client({"xp": [spot, trees]})
        circuit = self.circuit(client, spot)
        circuit.child.navigation.status = TaskStatus.COMPLETE
        client.state.map.path = self.BURNT_16_74
        farm = circuit.child.task
        until = time.monotonic() + FarmTask.OUT_OF_LEAGUE_SECONDS
        # The bear is not marked: she may still pull it.
        client.out_of_league_kinds = {"charred treant": until,
                                      "singed deer": until}
        self.assertFalse(circuit._observe_out_of_league(client))
        self.assertFalse(circuit._upgrade_progression(client, farm))
        self.assertEqual(circuit.spot["name"], "Burnt Forest")
        client.out_of_league_kinds["singed bear"] = until
        self.assertTrue(circuit._observe_out_of_league(client))
        self.assertGreater(
            client.state.farm_zone_quarantine[self.BURNT_16_74], time.time())
        self.assertIn("farm-out-of-league",
                      [entry["action"] for entry in client.decision_history])
        # The analyzer choice moves her on, by her ordinary walk.
        self.assertTrue(circuit._upgrade_progression(client, farm))
        self.assertEqual(circuit.spot["name"], "Trees")
        self.assertEqual(circuit.child.navigation.destination, self.TREES)

    def test_a_spot_whose_every_resident_kind_is_out_of_league_is_never_picked(self):
        # Picked, it was quarantined as soon as she arrived
        # (farm-out-of-league): the analyzer choice skips it while the
        # marks last.
        from .navigation import _analyzer_farm_choice

        graph = built_graph()
        spot = analyzer_spot("Burnt Forest", [self.BURNT_16_74],
                             ["charred treant L33"])
        trees = analyzer_spot("Trees", [self.TREES], ["evil treant L13"])
        client = self.client({"xp": [spot, trees]})
        self.assertEqual(_analyzer_farm_choice(client, graph)[2]["name"],
                         "Burnt Forest")
        until = time.monotonic() + FarmTask.OUT_OF_LEAGUE_SECONDS
        # One resident kind she may still pull keeps the spot.
        client.out_of_league_kinds = {"charred treant": until,
                                      "singed deer": until}
        self.assertEqual(_analyzer_farm_choice(client, graph)[2]["name"],
                         "Burnt Forest")
        client.out_of_league_kinds["singed bear"] = until
        self.assertEqual(_analyzer_farm_choice(client, graph)[2]["name"],
                         "Trees")
        # Expired marks no longer count.
        client.out_of_league_kinds = {
            kind: time.monotonic() - 1.0 for kind in client.out_of_league_kinds}
        self.assertEqual(_analyzer_farm_choice(client, graph)[2]["name"],
                         "Burnt Forest")

    def test_failures_at_an_analyzer_spot_teach_instead_of_excluding_it(self):
        trees = analyzer_spot("Trees", [self.TREES], ["evil treant L13"])
        pocket = analyzer_spot("Pocket", [self.POCKET], ["evil treant L13"])
        client = self.client({"xp": [trees, pocket]})
        circuit = self.circuit(client, trees)
        farm = circuit.child.task
        base = (farm.safety.flee_below, farm.safety.heal_below)
        # Two treants hitting at once, then a death on the spot.
        client.state.add_message(2, "ff0000", "evil treant hit you for 30 (-30) impact damage.")
        client.state.add_message(2, "ff0000", "quickwood hit you for 20 (-20) impact damage.")
        client.decision_history.append({
            "time": time.time() + 1, "action": "death", "detail": "",
            "task": "", "map": self.TREES})
        self.assertFalse(circuit._observe_farm_death(client))
        self.assertNotIn(self.TREES, client.state.farm_zone_quarantine)
        record = client.state.farm_adaptations[trees["path"]]
        self.assertEqual(record["level"], 1)
        self.assertEqual(record["causes"], {"pack": 1})
        self.assertEqual(record["reviews"][-1]["peak_attackers"], 2)
        self.assertIn("area spells for packs", record["reviews"][-1]["remedies"])
        rebuilt = circuit.child.task
        self.assertIsNot(rebuilt, farm)
        self.assertEqual((rebuilt.safety.flee_below, rebuilt.safety.heal_below),
                         (round(base[0] + 0.03, 6), round(base[1] + 0.02, 6)))
        self.assertIn("farm-failure-review",
                      [entry["action"] for entry in client.decision_history])
        # The analyzer's pick is unchanged: the spot is kept.
        self.assertFalse(circuit._upgrade_progression(client, rebuilt))
        self.assertEqual(circuit.spot["name"], "Trees")
        # An emergency recall there teaches again, and the rebuilt task keeps
        # the recall in flight instead of firing another.
        rebuilt._emergency_recall_cast_at = 123.0
        rebuilt._emergency_recall_origin = self.TREES
        client.decision_history.append({
            "time": time.time() + 2, "action": "emergency-recall", "detail": "",
            "task": "", "map": self.TREES})
        self.assertFalse(circuit._observe_farm_death(client))
        self.assertEqual(client.state.farm_adaptations[trees["path"]]["level"], 2)
        self.assertIsNot(circuit.child.task, rebuilt)
        self.assertEqual((circuit.child.task._emergency_recall_cast_at,
                          circuit.child.task._emergency_recall_origin),
                         (123.0, self.TREES))
        # Once the pick is reached, a failure elsewhere, long after she was
        # last at the spot and not beside it, does not count.
        circuit.child.navigation.complete()
        client.decision_history.append({
            "time": time.time() + 3 + 2 * circuit.FARM_SEAM_FAILURE_SECONDS,
            "action": "death", "detail": "", "task": "", "map": "/elsewhere"})
        self.assertFalse(circuit._observe_farm_death(client))
        self.assertEqual(client.state.farm_adaptations[trees["path"]]["level"], 2)

    def test_empty_recall_wand_falls_back_after_circuit_failure_rebuild(self):
        from .tasks import wand_charges

        trees = analyzer_spot("Trees", [self.TREES], ["evil treant L13"])
        client = self.client({"xp": [trees]})
        client.state.map.path = self.TREES
        client.state.stats["sp"] = 30
        wand = Item(77, item_type=c.TYPE_WAND, quality=80, condition=80,
                    flags=c.ITEM_APPLIED,
                    name="pine wand of word of recall (lvl 17)")
        spell = Item(71, item_type=c.TYPE_SPELL, name="word of recall",
                     extra={"cost": 24})
        client.state.place_item(wand, client.state.player_tag)
        client.state.place_item(spell, client.state.player_tag)
        fired = []

        async def send(packet):
            pass

        async def fire(direction, tag=0):
            fired.append((direction, tag))

        client.send = send
        client.fire = fire
        circuit = self.circuit(client, trees)
        previous = circuit.child.task
        self.assertTrue(asyncio.run(previous.emergency_recall(
            client, ratio=0.30, nearby_count=1, hostile_contact=True)))
        self.assertEqual(fired, [(0, 0)])
        # An earlier recall's decision triggers the circuit's adaptation and
        # child rebuild before the server reports that the wand was empty.
        client.decision_history.append({
            "time": time.time(), "action": "emergency-recall", "detail": "",
            "task": "", "map": self.TREES})
        self.assertFalse(circuit._observe_farm_death(client))
        rebuilt = circuit.child.task
        self.assertIsNot(rebuilt, previous)
        client.state.add_message(2, "ffffff", "The wand says poof.")
        self.assertTrue(asyncio.run(rebuilt.emergency_recall(
            client, ratio=0.30, nearby_count=1, hostile_contact=True)))
        self.assertEqual(fired, [(0, 0), (0, 71)])
        self.assertEqual(wand_charges(client)[77], 0)
        self.assertIn("recall-wand-empty",
                      [entry["action"] for entry in client.decision_history])

