        circuit._shopping = _DoneErrand(status=TaskStatus.RUNNING)
        circuit._bed_binding = _DoneErrand(status=TaskStatus.RUNNING)
        circuit._banking = _DoneErrand(status=TaskStatus.RUNNING)
