    def test_mana_crystal_backoff_survives_a_restart(self):
        with tempfile.TemporaryDirectory() as directory:
            path = str(Path(directory) / "state.json")

            def started_client():
                client = AtrinikClient(ClientConfig(
                    character="Sera", runtime_state_path=path))
                client.state.player_name = "Sera"
                client.load_character_memory("Sera")

                async def send(packet):
                    pass

                client.send = send
                return client

            client = started_client()
            client.state.phase = "playing"
            client.state.stats.update(level=36, hp=134, maxhp=134, food=900)
            client.state.quests_loaded = True
            client.state.quests = {
                AutoplayTask.MANA_CRYSTAL_QUEST: QuestProgress(
                    AutoplayTask.MANA_CRYSTAL_QUEST, status="incomplete",
                    parts=[QuestPartProgress("A Better Crystal",
                                             status="active")])}
            autoplay = AutoplayTask(WorldGraph())
            autoplay.phase = "mana-crystal-upgrade"
            autoplay.child = ManaCrystalUpgradeTask(WorldGraph())
            autoplay.child.fail("death during the trip")
            asyncio.run(autoplay.tick(client))
            self.assertIsNone(autoplay.child)
            self.assertFalse(autoplay._needs_mana_crystal_upgrade(client))

            restarted = started_client()
            # The failure's records are gone (a loop filled the history).
            restarted.decision_history = []
            restarted.state.phase = "playing"
            restarted.state.stats.update(level=36, hp=134, maxhp=134)
            restarted.state.quests_loaded = True
            restarted.state.quests = client.state.quests
            self.assertAlmostEqual(
                restarted.state.mana_crystal_retry_until["upgrade"],
                time.time() + AutoplayTask.MANA_CRYSTAL_UPGRADE_RETRY,
                delta=60)
            self.assertFalse(
                AutoplayTask(WorldGraph())._needs_mana_crystal_upgrade(restarted))
            # Once the deadline passes, it is due again.
            restarted.state.mana_crystal_retry_until = {
                "upgrade": time.time() - 1}
            self.assertTrue(
                AutoplayTask(WorldGraph())._needs_mana_crystal_upgrade(restarted))

    def unprepared_circuit(self, client, needs, *, legs=None, clock=None):
        """A circuit at the point where it starts optional trips, with
        only ``needs`` due."""
        circuit = FarmCircuitTask(
            built_graph(), legs or [(self.TREES, "")],
            **({"clock": clock} if clock is not None else {}))
        circuit._busy_finishing_fight_or_loot = lambda client, farm: False
        client.state.inventory_replay_complete = True
        circuit.server_clock.anchor_minute = 12 * 60
        circuit.server_clock.anchor_at = circuit.server_clock.clock()
        circuit.server_clock.last_request_at = circuit.server_clock.clock()
        circuit.server_clock.resync_seconds = float("inf")
        for name in ("_needs_bank_sync", "_needs_progress_checkpoint",
                     "_needs_bank_deposit", "_needs_ship_key",
                     "_needs_food_resupply", "_needs_savebed",
                     "_needs_spell_purchase", "_needs_recall_shopping",
                     "_needs_utility_shopping", "_needs_upgrade_shopping",
                     "_needs_heal_restock"):
            setattr(circuit, name, lambda *args, due=(name == needs): due)
        return circuit

    def test_the_circuit_starts_no_optional_trip_without_heals_or_recall(self):
        from .tasks import UNPREPARED_REST_LIMIT_SECONDS, unprepared_for_trips

        for needs, trip in (("_needs_spell_purchase", "_spell_purchase"),
                            ("_needs_ship_key", "_ship_key"),
                            ("_needs_recall_shopping", "_recall_shopping"),
                            ("_needs_utility_shopping", "_utility_shopping"),
                            ("_needs_upgrade_shopping", "_shopping")):
            # 80 %: above every heal and flee threshold, below 90 %.
            client, _ = self.client(recall=False, bank=20_000)
            client.state.place_item(Item(
                90, name="Morg'eean's Ship Key"), client.state.player_tag)
            client.state.stats.update(hp=107, maxhp=134)
            self.assertTrue(unprepared_for_trips(client))
            circuit = self.unprepared_circuit(client, needs)
            for _ in range(3):
                asyncio.run(circuit.tick(client))
            self.assertIsNone(getattr(circuit, trip), needs)
            client.state.stats["hp"] = 121
            asyncio.run(circuit.tick(client))
            self.assertIsNotNone(getattr(circuit, trip), needs)
        # The hold lasts at most ten minutes in a row, then she goes.
        client, _ = self.client(recall=False, bank=20_000)
        client.state.stats.update(hp=107, maxhp=134)
        circuit = self.unprepared_circuit(client, "_needs_spell_purchase")
        for _ in range(3):
            asyncio.run(circuit.tick(client))
        self.assertIsNone(circuit._spell_purchase)
        circuit._unprepared_hold.since -= UNPREPARED_REST_LIMIT_SECONDS
        asyncio.run(circuit.tick(client))
        self.assertIsNotNone(circuit._spell_purchase)
        self.assertEqual(self.actions(client).count("unprepared-rest-timeout"), 1)

    def test_a_pending_survival_ranking_holds_lesser_trips(self):
        # While the food, heal or recall ranking runs on the planner
        # worker, no lesser trip starts in its place.
        import threading
        from . import planner as planner_module

        release = threading.Event()
        self.addCleanup(release.set)
        self.enterContext(patch.object(planner_module, "submit",
                                       planner_module.worker().submit))

        def pending(*_args, **_kwargs):
            release.wait(5)

        for pending_need, builder, lesser, trip in (
                ("_needs_food_resupply", "_new_food_resupply",
                 "_needs_spell_purchase", "_spell_purchase"),
                ("_needs_heal_restock", "_new_heal_restock",
                 "_needs_spell_purchase", "_spell_purchase"),
                ("_needs_recall_shopping", "_new_recall_shopping",
                 "_needs_utility_shopping", "_utility_shopping")):
            with self.subTest(pending_need):
                client, _ = self.client(recall=False, bank=20_000)
                client.state.stats.update(hp=121, maxhp=134)
                circuit = self.unprepared_circuit(client, lesser)
                setattr(circuit, pending_need, lambda *args: True)
                setattr(circuit, builder, pending)
                circuit._heal_restock_may_leave = lambda *args: True
                for _ in range(2):
                    asyncio.run(circuit.tick(client))
                self.assertIsNone(getattr(circuit, trip))
                self.assertTrue(circuit._plans._plans)
                # Once it is no longer due, the lesser trip goes.
                setattr(circuit, pending_need, lambda *args: False)
                asyncio.run(circuit.tick(client))
                self.assertIsNotNone(getattr(circuit, trip))

    # The heal restock (COMBAT.md, "Healing-potion restock").
    def heal_circuit(self, client, graph=None):
        client.state.inventory_replay_complete = True
        return FarmCircuitTask(graph or built_graph(), [("/recovery", "")])

    @staticmethod
    def quote_heal(client, cost, *, age=0.0):
        from .navigation import HEAL_QUOTE_KEY

        client.state.vendor_quotes[HEAL_QUOTE_KEY] = {
            "item": "balm of minor healing", "unit_cost": cost,
            "observed_at": time.time() - age}

    def test_heal_restock_is_due_below_its_low_mark_and_only_then(self):
        from .tasks import heal_consumables

        client, _ = self.client(bank=5_000)
        tag = client.state.player_tag
        circuit = self.heal_circuit(client)
        self.assertTrue(circuit._needs_heal_restock(client))
        # Two usable balms: at the low mark, no trip.
        client.state.place_item(Item(
            91, item_type=c.TYPE_POTION, quality=80, quantity=2,
            name="balm of minor healing"), tag)
        self.assertEqual(heal_consumables(client), 2)
        self.assertFalse(circuit._needs_heal_restock(client))
        client.state.remove_item(91)
        # Unpaid or cursed potions are no heals of hers.
        client.state.place_item(Item(
            92, item_type=c.TYPE_POTION, quality=80, quantity=3,
            flags=c.ITEM_UNPAID, name="potion of minor healing"), tag)
        client.state.place_item(Item(
            94, item_type=c.TYPE_POTION, quality=80, quantity=3,
            flags=c.ITEM_CURSED, name="balm of greater healing"), tag)
        self.assertEqual(heal_consumables(client), 0)
        self.assertTrue(circuit._needs_heal_restock(client))
        # A scroll counts only while she reads scrolls.
        client.state.place_item(Item(
            93, item_type=c.TYPE_SCROLL, quality=80, quantity=4,
            name="paper scroll of minor healing (lvl 20)"), tag)
        self.assertTrue(circuit._needs_heal_restock(client))
        for skill_tag, skill in ((95, "literacy"), (96, "wizardry spells")):
            client.state.place_item(Item(
                skill_tag, item_type=c.TYPE_SKILL, name=skill), tag)
        self.assertEqual(heal_consumables(client), 4)
        self.assertFalse(circuit._needs_heal_restock(client))
        # Below level 18 nothing makes her rest for want of heals: no trip.
        client, _ = self.client(bank=5_000, level=17)
        self.assertFalse(self.heal_circuit(client)._needs_heal_restock(client))
        # Depletion due: the recovery phase comes first.
        client, _ = self.client(bank=5_000, depletion=92)
        self.assertFalse(self.heal_circuit(client)._needs_heal_restock(client))
        # Backing off, or too heavily loaded to carry them.
        client, _ = self.client(bank=5_000)
        circuit = self.heal_circuit(client)
        client.state.heal_restock_retry_until = time.time() + 60
        self.assertFalse(circuit._needs_heal_restock(client))
        client.state.heal_restock_retry_until = 0.0
        client.state.stats["weight_limit"] = 100.0
        client.state.place_item(Item(97, weight=90.0, name="rock"), tag)
        self.assertFalse(circuit._needs_heal_restock(client))

    def test_heal_restock_keeps_the_reserve_and_reads_fresh_quotes(self):
        client, _ = self.client(bank=FarmCircuitTask.HEAL_RESTOCK_MINIMUM_WALLET - 1)
        circuit = self.heal_circuit(client)
        self.assertFalse(circuit._needs_heal_restock(client))
        client.state.bank_balance += 1
        self.assertTrue(circuit._needs_heal_restock(client))
        # Quoted 600 copper: that plus the reserve.
        self.quote_heal(client, 600)
        self.assertFalse(circuit._needs_heal_restock(client))
        client.state.bank_balance = 600 + FarmCircuitTask.HEAL_RESTOCK_RESERVE
        self.assertTrue(circuit._needs_heal_restock(client))
        # A quote a day old is no price.
        client.state.bank_balance = FarmCircuitTask.HEAL_RESTOCK_MINIMUM_WALLET
        self.quote_heal(client, 600, age=FarmCircuitTask.HEAL_RESTOCK_INTERVAL)
        self.assertTrue(circuit._needs_heal_restock(client))

    def test_heal_restock_goes_to_a_merchant_with_healing_stock(self):
        from .navigation import heal_restock_vendors
        from .tasks import BuyHealingStockTask

        client, _ = self.client(bank=5_000)
        client.state.place_item(Item(
            90, name="Morg'eean's Ship Key"), client.state.player_tag)
        client.state.place_item(Item(
            91, item_type=c.TYPE_POTION, quality=80,
            name="balm of minor healing"), client.state.player_tag)
        circuit = self.heal_circuit(client)
        vendors = {(vendor.map_path, vendor.name): fixed
                   for vendor, fixed in heal_restock_vendors(built_graph(), client)}
        # The Asteria merchant's scroll of minor healing is authored stock
        # only once she reads scrolls; both roll random potions.
        self.assertEqual(vendors.get(
            ("/shattered_islands/world_4_47", "merchant")), False)
        self.assertIn(("/shattered_islands/world_17_2_5", "Leria"), vendors)
        # Feldain's minor healing is a spell, not a consumable.
        self.assertNotIn(("/shattered_islands/world_1_69", "Feldain Goodwin"),
                         vendors)
        trip = circuit._new_heal_restock(client, strict=False)
        self.assertIsNotNone(trip)
        self.assertEqual((trip.navigation.destination, trip.task.merchant),
                         ("/shattered_islands/world_4_47", "merchant"))
        self.assertIsInstance(trip.task, BuyHealingStockTask)
        # Up to the target from the one balm she has, keeping the reserve.
        self.assertEqual(trip.task.quantity,
                         FarmCircuitTask.HEAL_RESTOCK_TARGET - 1)
        self.assertEqual(trip.task.cash_reserve,
                         FarmCircuitTask.HEAL_RESTOCK_RESERVE)
        self.assertEqual(trip.task.observation_key, "heal-restock")
        self.assertEqual((trip.safety.heal_below, trip.safety.flee_below),
                         FarmCircuitTask.HEAL_RESTOCK_SAFETY)
        # An optional trip: never essential, so it never crosses an owner
        # block.
        self.assertEqual(trip.navigation.essential, "")
        self.assertFalse(trip.navigation.strict_safety)
        # From Brynknot no route reaches Asteria without the crocodile road:
        # the trip may cross it, as recall shopping's does...
        self.assertTrue(trip.navigation.allow_ranged_hazard_fallback)
        self.assertTrue(trip.hostile_transit)
        self.assertNotIn("navigation-threat-fallback", self.actions(client))
        # ...but never while unprepared, when only a strict route will do.
        self.assertIsNone(circuit._new_heal_restock(client, strict=True))
        # Where a strict route exists (in Asteria), that is the trip.
        self.place(client, ("/shattered_islands/world_4_46", (10, 10)))
        strict = circuit._new_heal_restock(client, strict=True)
        self.assertEqual(strict.navigation.destination,
                         "/shattered_islands/world_4_47")
        self.assertTrue(strict.navigation.strict_safety)
        self.assertFalse(strict.navigation.allow_ranged_hazard_fallback)
        self.assertFalse(strict.hostile_transit)
        # No merchant that sells heals: no trip.
        self.assertIsNone(self.heal_circuit(client, WorldGraph())
                          ._new_heal_restock(client, strict=False))
        # Nor one no route reaches, even with the hostile-transit fallback.
        from .navigation import DialogueVendor
        nowhere = DialogueVendor("/nowhere", 1, 1, "ghost",
                                 "/python/generic/merchant.py",
                                 ("scroll min heal",), ("random_potion",))
        with patch("atrinik_bot.navigation.heal_restock_vendors",
                   return_value=[(nowhere, True)]):
            self.assertIsNone(circuit._new_heal_restock(client, strict=False))

    def test_heal_restock_backs_off_without_a_seller_or_stock(self):
        from .navigation import heal_restock_alerts
        from .tasks import BuyHealingStockTask

        client, _ = self.client(bank=5_000)
        circuit = self.unprepared_circuit(client, "")
        circuit._needs_heal_restock = FarmCircuitTask._needs_heal_restock.__get__(
            circuit)
        planned = []

        def nowhere(client, *, strict):
            planned.append(strict)
            return None

        circuit._new_heal_restock = nowhere
        for _ in range(3):
            asyncio.run(circuit.tick(client))
        # One look, then a day's backoff, noted on the dashboard.
        self.assertEqual(planned, [False])
        self.assertIsNone(circuit._heal_restock)
        self.assertIn("no reachable merchant", client.state.heal_restock_note)
        self.assertGreater(client.state.heal_restock_retry_until,
                           time.time() + FarmCircuitTask.HEAL_RESTOCK_INTERVAL - 60)
        self.assertEqual(self.actions(client).count("heal-restock-backoff"), 1)
        alerts = heal_restock_alerts(client)
        self.assertEqual(self.ids(alerts), ["heal-restock-unavailable"])
        self.assertEqual(alerts[0]["level"], "info")
        autoplay = AutoplayTask(built_graph(), target_level=115)
        autoplay.status = TaskStatus.RUNNING
        self.assertIn("heal-restock-unavailable",
                      self.ids(autoplay.recovery_alerts(client)[0]))
        # Heals found some other way: the note no longer shows.
        client.state.place_item(Item(
            91, item_type=c.TYPE_POTION, quality=80, quantity=2,
            name="balm of minor healing"), client.state.player_tag)
        self.assertEqual(heal_restock_alerts(client), [])
        client.state.remove_item(91)

        def settle(status=TaskStatus.COMPLETE, error="", bought=0):
            shopper = BuyHealingStockTask("merchant", quantity=5)
            shopper.purchased = bool(bought)
            shopper.bought, shopper.bought_name = bought, "balm of minor healing"
            errand = _DoneErrand(status=status, task=shopper, error=error)
            errand.navigation = types.SimpleNamespace(
                destination="/shattered_islands/world_4_47")
            circuit._heal_restock = errand
            self.assertTrue(asyncio.run(circuit._tick_running_service(client)))
            self.assertIsNone(circuit._heal_restock)
            return client.state.heal_restock_retry_until - time.time()

        # The merchant had nothing she can use: a day.
        wait = settle()
        self.assertIn("no healing stock", client.state.heal_restock_note)
        self.assertGreater(wait, FarmCircuitTask.HEAL_RESTOCK_INTERVAL - 60)
        # A failed trip (she could pay for none): two hours.
        wait = settle(TaskStatus.FAILED, "healing stock costs at least 6s")
        self.assertIn("costs at least 6s", client.state.heal_restock_note)
        self.assertLess(wait, FarmCircuitTask.HEAL_RESTOCK_RETRY_SECONDS + 1)
        self.assertIn("costs at least 6s", heal_restock_alerts(client)[0]["text"])
        # Bought, but fewer than the low mark: the stock ran short, a day.
        client.state.place_item(Item(
            91, item_type=c.TYPE_POTION, quality=80,
            name="balm of minor healing"), client.state.player_tag)
        wait = settle(bought=1)
        self.assertIn("ran short", client.state.heal_restock_note)
        self.assertGreater(wait, FarmCircuitTask.HEAL_RESTOCK_INTERVAL - 60)
        # Bought enough: the note is cleared, and the next waits two hours
        # (at high level one fight can use all five), with no alert.
        client.state.items[91].quantity = 5
        wait = settle(bought=5)
        self.assertEqual(client.state.heal_restock_note, "")
        self.assertGreater(wait, FarmCircuitTask.HEAL_RESTOCK_MIN_INTERVAL - 60)
        self.assertLess(wait, FarmCircuitTask.HEAL_RESTOCK_MIN_INTERVAL + 1)
        client.state.remove_item(91)
        self.assertFalse(circuit._needs_heal_restock(client))
        self.assertEqual(heal_restock_alerts(client), [])
        client.state.heal_restock_retry_until = time.time() - 1
        self.assertTrue(circuit._needs_heal_restock(client))

    def test_heal_restock_is_the_one_optional_trip_an_unprepared_hold_allows(self):
        from .tasks import UNPREPARED_REST_LIMIT_SECONDS, unprepared_for_trips

        def setup(hp, *, plan=True):
            client, _ = self.client(recall=False, bank=20_000)
            client.state.place_item(Item(
                90, name="Morg'eean's Ship Key"), client.state.player_tag)
            client.state.stats.update(hp=hp, maxhp=134)
            circuit = self.unprepared_circuit(client, "_needs_heal_restock")
            # The spell purchase is due too, and stays held.
            circuit._needs_spell_purchase = lambda client: True
            planned = []

            def trip(client, *, strict):
                planned.append(strict)
                if not plan:
                    return None
                errand = _DoneErrand(status=TaskStatus.RUNNING)
                errand.task.merchant = "merchant"
                errand.navigation = types.SimpleNamespace(
                    destination="/shattered_islands/world_4_47")
                return errand

            circuit._new_heal_restock = trip
            if not plan:
                circuit._needs_heal_restock = (
                    FarmCircuitTask._needs_heal_restock.__get__(circuit))
            return client, circuit, planned

        # 80 %: unprepared, above the trip's flee threshold. She goes, by a
        # strict route only; the spell purchase still waits.
        client, circuit, planned = setup(107)
        self.assertTrue(unprepared_for_trips(client))
        for _ in range(3):
            asyncio.run(circuit.tick(client))
        self.assertEqual(planned, [True])
        self.assertIsNotNone(circuit._heal_restock)
        self.assertIsNone(circuit._spell_purchase)
        self.assertIn("heal-restock", self.actions(client))
        # 60 %: below it the farm's unprepared rest regenerates her first.
        client, circuit, planned = setup(80)
        for _ in range(3):
            asyncio.run(circuit.tick(client))
        self.assertEqual(planned, [])
        self.assertIsNone(circuit._heal_restock)
        self.assertIsNone(circuit._spell_purchase)
        # Once the hold's ten minutes run out, it goes like any optional
        # trip, ahead of the others.
        circuit._unprepared_hold.since -= UNPREPARED_REST_LIMIT_SECONDS
        asyncio.run(circuit.tick(client))
        self.assertEqual(planned, [False])
        self.assertIsNone(circuit._spell_purchase)
        # Prepared again (90 %): the ordinary route.
        client, circuit, planned = setup(121)
        self.assertFalse(unprepared_for_trips(client))
        for _ in range(3):
            asyncio.run(circuit.tick(client))
        self.assertEqual(planned, [False])
        # Unprepared and no strict route: no day's backoff, only a short
        # wait, and nothing on the dashboard.
        client, circuit, planned = setup(107, plan=False)
        for _ in range(3):
            asyncio.run(circuit.tick(client))
        self.assertEqual(planned, [True])
        self.assertEqual(client.state.heal_restock_note, "")
        self.assertEqual(self.actions(client).count("heal-restock-deferred"), 1)
        self.assertGreater(circuit._heal_restock_retry_at, circuit.clock())
        self.assertIn("_heal_restock_retry_at", circuit.backoffs())
        # Farming turning unsafe drops it like the other optional trips.
        client, circuit, planned = setup(107)
        for _ in range(3):
            asyncio.run(circuit.tick(client))
        self.assertIn("errand", circuit.drop_discretionary_trips(client))
        self.assertIsNone(circuit._heal_restock)

    def test_a_hostile_road_restock_departs_only_at_full_hp_and_sp(self):
        def setup(hp, sp, *, recall=False):
            client, _ = self.client(recall=recall, bank=20_000)
            client.state.stats.update(hp=hp, maxhp=134, sp=sp, maxsp=20)
            circuit = self.unprepared_circuit(client, "")
            circuit._needs_heal_restock = (
                FarmCircuitTask._needs_heal_restock.__get__(circuit))
            planned = []

            def trip(client, *, strict):
                planned.append(strict)
                errand = _DoneErrand(status=TaskStatus.RUNNING)
                errand.task.merchant = "merchant"
                errand.navigation = types.SimpleNamespace(
                    destination="/shattered_islands/world_4_47")
                errand.hostile_transit = True
                return errand

            circuit._new_heal_restock = trip
            return client, circuit, planned

        def farm(circuit):
            return circuit.child.task

        # 95 %: not unprepared, but no heal and no recall, and the road is
        # hostile: she waits, and the farm pulls nothing meanwhile.
        client, circuit, planned = setup(127, 20)
        for _ in range(3):
            asyncio.run(circuit.tick(client))
        self.assertEqual(planned, [False])
        self.assertIsNone(circuit._heal_restock)
        self.assertTrue(farm(circuit).rest_for_departure)
        self.assertEqual(self.actions(client).count("heal-restock-waits"), 1)
        self.assertNotIn("heal-restock-backoff", self.actions(client))
        # Full HP and SP: re-planned at once, and she goes.
        client.state.stats.update(hp=134, sp=20)
        asyncio.run(circuit.tick(client))
        self.assertEqual(planned, [False, False])
        self.assertIsNotNone(circuit._heal_restock)
        self.assertFalse(farm(circuit).rest_for_departure)
        # Full HP but SP short counts as not full.
        client, circuit, planned = setup(134, 10)
        asyncio.run(circuit.tick(client))
        self.assertIsNone(circuit._heal_restock)
        # A ready recall: no wait, she goes at once.
        client, circuit, planned = setup(127, 20, recall=True)
        for _ in range(3):
            asyncio.run(circuit.tick(client))
        self.assertIsNotNone(circuit._heal_restock)
        # Ten minutes without getting full: a two-hour backoff, and the
        # farm farms again.
        client, circuit, planned = setup(127, 20)
        for _ in range(3):
            asyncio.run(circuit.tick(client))
        circuit._heal_restock_full_since -= (
            FarmCircuitTask.HEAL_RESTOCK_FULL_WAIT_SECONDS)
        asyncio.run(circuit.tick(client))
        self.assertIsNone(circuit._heal_restock)
        self.assertIn("full HP and SP", client.state.heal_restock_note)
        self.assertFalse(farm(circuit).rest_for_departure)

    def test_a_departure_wait_ends_with_its_need_and_survives_a_rebuild(self):
        client, _ = self.client(recall=False, bank=20_000)
        client.state.stats.update(hp=127, maxhp=134, sp=20, maxsp=20)
        circuit = self.unprepared_circuit(client, "")
        circuit._needs_heal_restock = (
            FarmCircuitTask._needs_heal_restock.__get__(circuit))

        def trip(client, *, strict):
            errand = _DoneErrand(status=TaskStatus.RUNNING)
            errand.task.merchant = "merchant"
            errand.navigation = types.SimpleNamespace(
                destination="/shattered_islands/world_4_47")
            errand.hostile_transit = True
            return errand

        circuit._new_heal_restock = trip
        for _ in range(3):
            asyncio.run(circuit.tick(client))
        self.assertIsNotNone(circuit._heal_restock_full_since)
        # An explained wait for the stuck alert, like an unprepared rest.
        self.assertTrue(circuit.unprepared_resting())
        autoplay = AutoplayTask(built_graph(), target_level=115)
        autoplay.status = TaskStatus.RUNNING
        autoplay.child = circuit
        self.assertTrue(autoplay.recovery_alerts(client)[1])
        # A rebuilt circuit (after a recovery phase, say) keeps the re-plan
        # pause but starts the bounded wait afresh: an old start would back
        # off at once without waiting.
        backoffs = circuit.backoffs()
        self.assertNotIn("_heal_restock_full_since", backoffs)
        rebuilt = FarmCircuitTask(built_graph(), [(self.TREES, "")],
                                  backoffs=backoffs)
        self.assertIsNone(rebuilt._heal_restock_full_since)
        self.assertGreater(rebuilt._heal_restock_retry_at, rebuilt.clock())
        # The money gone below the reserve: the wait ends, the farm farms,
        # and no backoff is written for it.
        client.state.bank_balance = 500
        asyncio.run(circuit.tick(client))
        self.assertIsNone(circuit._heal_restock_full_since)
        self.assertFalse(circuit.child.task.rest_for_departure)
        self.assertFalse(circuit.unprepared_resting())
        self.assertEqual(client.state.heal_restock_note, "")
        self.assertNotIn("heal-restock-backoff", self.actions(client))
        # Likewise when a backoff comes into force while it waits.
        client.state.bank_balance = 20_000
        circuit._heal_restock_retry_at = 0.0
        asyncio.run(circuit.tick(client))
        self.assertIsNotNone(circuit._heal_restock_full_since)
        client.state.heal_restock_retry_until = time.time() + 60
        asyncio.run(circuit.tick(client))
        self.assertIsNone(circuit._heal_restock_full_since)
        self.assertFalse(circuit.child.task.rest_for_departure)

    def test_an_unusable_heal_is_no_heal_for_safety_or_restock(self):
        from .tasks import heal_consumables, unprepared_for_trips

        client, _ = self.client(recall=False, bank=5_000)
        client.state.stats.update(hp=107, maxhp=134, sp=0)
        client.state.inventory_replay_complete = True
        tag = client.state.player_tag
        circuit = self.heal_circuit(client)
        # A scroll she cannot read, an unpaid and a cursed potion, an
        # unidentified one and a spellbook: neither her safety policy nor
        # the restock counts any of them.
        for item in (
                Item(81, item_type=c.TYPE_SCROLL, quality=80,
                     name="paper scroll of minor healing (lvl 20)"),
                Item(82, item_type=c.TYPE_POTION, quality=80,
                     flags=c.ITEM_UNPAID, name="potion of minor healing"),
                Item(83, item_type=c.TYPE_POTION, quality=80,
                     flags=c.ITEM_CURSED, name="potion of minor healing"),
                Item(84, item_type=c.TYPE_POTION,
                     name="balm of minor healing"),
                Item(85, item_type=c.TYPE_SPELLBOOK, quality=80,
                     name="spellbook of minor healing")):
            client.state.place_item(item, tag)
        self.assertIsNone(SafetyPolicy()._usable_heal(client))
        self.assertTrue(unprepared_for_trips(client))
        self.assertEqual(heal_consumables(client), 0)
        self.assertTrue(circuit._needs_heal_restock(client))
        # Able to read it: both see the scroll.
        for skill_tag, skill in ((86, "literacy"), (87, "wizardry spells")):
            client.state.place_item(Item(
                skill_tag, item_type=c.TYPE_SKILL, name=skill), tag)
        self.assertEqual(SafetyPolicy()._usable_heal(client).tag, 81)
        self.assertFalse(unprepared_for_trips(client))
        self.assertEqual(heal_consumables(client), 1)

    def test_an_unprepared_farm_rest_is_no_stuck_wait_and_only_that(self):
        from .tasks import UNPREPARED_REST_LIMIT_SECONDS

        client, _ = self.client(recall=False)
        autoplay = AutoplayTask(built_graph(), target_level=115)
        autoplay.status = TaskStatus.RUNNING
        circuit = FarmCircuitTask(built_graph(), [(self.TREES, "")])
        circuit.child = circuit._new_child()
        autoplay.child = circuit
        farm = circuit.child.task
        # The farm shares its circuit's hold.
        self.assertIs(farm._unprepared_hold, circuit._unprepared_hold)
        hold = circuit._unprepared_hold
        self.assertFalse(autoplay.recovery_alerts(client)[1])
        farm._unprepared_resting = True
        hold.since = hold.last_poll = time.monotonic()
        self.assertTrue(autoplay.recovery_alerts(client)[1])
        # An essential trip (a bank deposit) runs after the rest started:
        # the stale rest flags no longer explain anything.
        circuit._banking = _DoneErrand(status=TaskStatus.RUNNING)
        self.assertFalse(autoplay.recovery_alerts(client)[1])
        circuit._banking = None
        # Nor while a food resupply trip runs.
        circuit._resupply = _DoneErrand(status=TaskStatus.RUNNING)
        self.assertFalse(autoplay.recovery_alerts(client)[1])
        circuit._resupply = None
        self.assertTrue(autoplay.recovery_alerts(client)[1])
        # Nor does a rest nobody has checked for a while (the farm returned
        # early before its rest branch), nor one past its cap.
        hold.last_poll -= 5.0
        self.assertFalse(autoplay.recovery_alerts(client)[1])
        hold.last_poll = time.monotonic()
        hold.since -= UNPREPARED_REST_LIMIT_SECONDS
        self.assertFalse(autoplay.recovery_alerts(client)[1])

    def test_a_gap_in_the_hold_starts_it_afresh(self):
        # Four minutes of rest, then a seven-minute essential trip: she
        # rests again rather than timing out at once.
        from .tasks import UnpreparedHold

        client, _ = self.client(recall=False)
        client.state.stats.update(hp=67, maxhp=134, sp=0)
        now = [1_000.0]
        hold = UnpreparedHold(clock=lambda: now[0])
        for _ in range(48):
            self.assertTrue(hold.active(client))
            now[0] += 5.0
        now[0] += 7 * 60
        self.assertTrue(hold.active(client))
        self.assertEqual(hold.since, now[0])
        self.assertNotIn("unprepared-rest-timeout", self.actions(client))

    def test_no_leg_switch_mid_rest_and_the_cap_still_fires_at_600_s(self):
        from .tasks import UNPREPARED_REST_LIMIT_SECONDS

        client, _ = self.client(recall=False)
        client.state.stats.update(hp=107, maxhp=134)
        node = built_graph().nodes[self.TREES]
        start = next((x, y) for x in range(node.width // 2, node.width)
                     for y in range(node.height // 2, node.height)
                     if node.walkable(x, y))
        self.place(client, (self.TREES, start))
        now = [1_000.0]
        circuit = self.unprepared_circuit(
            client, "", clock=lambda: now[0],
            legs=[(self.TREES, ""), ("/shattered_islands/world_14_78", "")])
        while now[0] - 1_000.0 < UNPREPARED_REST_LIMIT_SECONDS - 4:
            asyncio.run(circuit.tick(client))
            self.assertEqual(circuit.leg_index, 0, now[0] - 1_000.0)
            now[0] += 4.0
        self.assertGreater(now[0] - circuit._farm_started_at, circuit.dwell_seconds)
        self.assertIn("unprepared-rest", self.actions(client))
        self.assertNotIn("unprepared-rest-timeout", self.actions(client))
        for _ in range(3):
            now[0] += 4.0
            asyncio.run(circuit.tick(client))
        self.assertEqual(self.actions(client).count("unprepared-rest-timeout"), 1)
        # Past the cap the hold no longer keeps her on this leg: the dwell
        # switch moves her on.
        self.assertFalse(circuit._unprepared_hold.holding())
        now[0] += 4.0
        asyncio.run(circuit.tick(client))
        self.assertEqual(circuit.leg_index, 1)

