        client.state.add_message(c.CHAT_TYPE_GAME, "ffffff",
                                 "That is silksteel chain mail +1 (ac+6)")
        self.assertFalse(gear_examine_pending(client))
        asyncio.run(farm.check_recall_wand(client))
