    def test_a_ranged_hit_and_the_step_after_it(self):
        from . import owner_watch
        from .owner_watch import Creature, Frame, OwnerWatchRecorder
        recorder = OwnerWatchRecorder()
        node = terrain_node(TerrainTests.CORRIDOR)

        def frame(at, owner=None, animations=(), creatures=()):
            recorder.note(Frame(at, "Sera", "/t", node, owner, list(creatures), False,
                                list(animations)))
            return recorder.observe(at, "Sera")
        frame(100.0, (3, 3))
        # A hit with no monster next to it is ranged.
        frame(101.0, (3, 3), [(3, 3, c.ANIM_DAMAGE, 7)])
        engagement = recorder.engagement
        self.assertEqual((engagement.ranged_hits, engagement.stepped_after_ranged), (1, 0))
        frame(102.0, (2, 3))
        self.assertEqual(engagement.stepped_after_ranged, 1)
        # A hit with a monster next to it is no ranged hit.
        frame(103.0, (2, 3), [(2, 3, c.ANIM_DAMAGE, 2)], [Creature(1, 3, "orc", "")])
        self.assertEqual((engagement.ranged_hits, engagement.hits_taken), (1, 2))
        # Standing still past the window is no step.
        frame(104.0, (2, 3), [(2, 3, c.ANIM_DAMAGE, 2)])
        frame(108.0, (2, 3))
        frame(109.0, (3, 3))
        self.assertEqual((engagement.ranged_hits, engagement.stepped_after_ranged), (2, 1))
        # A kill marker on its own square is its death.
        frame(109.5, (3, 3), [(3, 3, c.ANIM_KILL, 0)])
        self.assertTrue(engagement.owner_died)
        # Out of view, the engagement ends and is kept.
        row, = frame(110.0)
        self.assertEqual((row["seconds"], row["peak_adjacent"], row["owner_died"]), (8.5, 1, 1))
        self.assertIsNone(recorder.last_end)
        # A fight cut at the limit is kept, and its successor measures no rest.
        with patch.object(owner_watch, "MAX_ENGAGEMENT_SECONDS", 2.0):
            frame(200.0, (3, 3), [(3, 3, c.ANIM_DAMAGE, 1)])
            row, = frame(202.5, (3, 3), [(3, 3, c.ANIM_DAMAGE, 1)])
        self.assertEqual(row["seconds"], 2.5)
        frame(203.0, (3, 3), [(3, 3, c.ANIM_DAMAGE, 1)])
        self.assertIsNone(recorder.engagement.gap_seconds)

    def test_each_animation_is_scored_against_its_own_frame(self):
        from . import owner_watch
        from .owner_watch import Creature, Frame, OwnerWatchRecorder
        recorder = OwnerWatchRecorder()
        node = terrain_node(TerrainTests.CORRIDOR)
        orc = Creature(5, 3, "orc", "")
        # Three generations in one engine step: a player is in view only in
        # the middle one, which strikes the orc beside the owner.
        recorder.note(Frame(1.0, "Sera", "/t", node, (4, 3), [orc], False,
                            [(5, 3, c.ANIM_DAMAGE, 3)]))
        recorder.note(Frame(1.1, "Sera", "/t", node, (4, 3), [orc], True,
                            [(5, 3, c.ANIM_DAMAGE, 40)]))
        recorder.note(Frame(1.2, "Sera", "/t", node, (4, 3), [orc], False))
        recorder.observe(1.3, "Sera")
        self.assertTrue(recorder.engagement.shared)
        self.assertEqual(recorder.observe(20.0, "Sera"), [])
        self.assertEqual(recorder.shared_dropped, 1)
        # The owner moved between generations: each hit is scored on the
        # square it stood on then. A hit beside its old square is not its.
        recorder.note(Frame(30.0, "Sera", "/t", node, (2, 3), [Creature(1, 3, "orc", "")],
                            False, [(1, 3, c.ANIM_DAMAGE, 5)]))
        recorder.note(Frame(30.1, "Sera", "/t", node, (4, 3),
                            [Creature(1, 3, "orc", ""), orc], False,
                            [(1, 3, c.ANIM_DAMAGE, 9), (5, 3, c.ANIM_DAMAGE, 6)]))
        recorder.observe(30.2, "Sera")
        self.assertEqual((recorder.engagement.hits_dealt, recorder.engagement.damage_dealt),
                         (2, 11))
        # A kill marker credits a kill only where a monster stood beside it,
        # now or in the frame before; the killing blow counts as a hit.
        recorder.note(Frame(30.3, "Sera", "/t", node, (4, 3), [], False,
                            [(5, 3, c.ANIM_KILL, 8), (3, 3, c.ANIM_KILL, 0)]))
        recorder.observe(30.4, "Sera")
        engagement = recorder.engagement
        self.assertEqual((engagement.kills, engagement.hits_dealt, engagement.damage_dealt),
                         (1, 3, 19))
        # Her own fight in any frame drops the engagement.
        recorder.note(Frame(30.5, "Sera", "/t", node, (4, 3), busy=True))
        recorder.observe(30.6, "Sera")
        self.assertIsNone(recorder.engagement)
        # Lost frames make an engagement shared.
        recorder.note(Frame(40.0, "Sera", "/t", node, (4, 3), [orc], False,
                            [(5, 3, c.ANIM_DAMAGE, 1)]))
        recorder.observe(40.1, "Sera")
        with patch.object(owner_watch, "MAX_FRAMES", 1):
            recorder.note(Frame(40.2, "Sera", "/t", node, (4, 3), [orc]))
            recorder.note(Frame(40.3, "Sera", "/t", node, (4, 3), [orc]))
        recorder.observe(40.4, "Sera")
        self.assertTrue(recorder.engagement.shared)
        # Lost frames with no engagement at the step's start: one begun in
        # them (a player may have been there) is shared too, until a frame
        # without one.
        recorder.reset()
        with patch.object(owner_watch, "MAX_FRAMES", 2):
            recorder.note(Frame(50.0, "Sera", "/t", node, (4, 3), [orc], True,
                                [(5, 3, c.ANIM_DAMAGE, 1)]))
            for at in (50.1, 50.2):
                recorder.note(Frame(at, "Sera", "/t", node, (4, 3), [orc], False,
                                    [(5, 3, c.ANIM_DAMAGE, 1)]))
        recorder.observe(50.3, "Sera")
        self.assertTrue(recorder.engagement.shared)
        self.assertEqual(recorder.observe(70.0, "Sera"), [])
        recorder.note(Frame(80.0, "Sera", "/t", node, (4, 3), [orc]))
        recorder.note(Frame(80.1, "Sera", "/t", node, (4, 3), [orc], False,
                            [(5, 3, c.ANIM_DAMAGE, 1)]))
        recorder.observe(80.2, "Sera")
        self.assertFalse(recorder.engagement.shared)

