    def test_stale_vitals_and_party_member_names(self):
        from .owner_watch import frame_of, name_digest
        client = self.client()
        self.put(client, 4, "Zoey", "ffffff", 7)
        client.state.operator_vitals = (60, 50, time.time() - 31)
        self.assertIsNone(frame_of(client, client.state.map).hp)
        client.state.operator_vitals = (60, 50, time.time())
        self.assertEqual(frame_of(client, client.state.map).hp, 60)
        # A green creature name a party member carries is never a monster,
        # even when not her friend (she may be berserk).
        self.put(client, 5, "orc", "00ff00", 8)
        self.assertEqual([cr.kind for cr in frame_of(client, client.state.map).creatures],
                         ["orc"])
        client.state.party_member_digests = {name_digest("Orc")}
        frame = frame_of(client, client.state.map)
        self.assertEqual((frame.creatures, frame.others), ([], True))
        # Joining a party starts afresh.
        raw = bytes((c.CMD_PARTY_JOIN,)) + b"Sera\0"
        asyncio.run(client._handle_party(Cursor(raw), raw))
        self.assertEqual((client.state.operator_vitals, client.state.party_member_digests),
                         (None, set()))

