    def test_a_chase_back_and_forth_forgets_its_old_landing(self):
        from . import route_events

        task = self.trip()
        self.into_hall(task)
        # Chased onto /goal far from the arrival square, then back.
        self.at(self.client, "/goal", 20, 20)
