        self.at(self.client, "/hall", 1, 27)
        self.clock[0] += 5
        route_events.note_hold(self.client, task)
        # Later the real crossing, seen first by a hold.
        self.clock[0] += 10
        self.at(self.client, "/goal", 5, 5)
        route_events.note_hold(self.client, task)
        landed = self.clock[0]
        self.at(self.client, "/goal", 9, 5)
