class RouteShadowTests(unittest.TestCase):
    """docs/ROUTING.md P6: shadow planning beside today's plans."""

    def setUp(self):
        from . import route_blocks, route_costs, route_shadow
        self.route_blocks, self.route_costs, self.route_shadow = (
            route_blocks, route_costs, route_shadow)
        self.directory = self.enterContext(tempfile.TemporaryDirectory())
        self.client = LearnedClient(Path(self.directory) / "memory.sqlite3")
        self.graph = blocks_graph()
        self.enterContext(patch.object(route_costs, "learned_model",
                                       lambda client, **_: getattr(client, "route_cost_source", client).route_model))

    def learn(self, *rows):
        self.client.route_model = self.route_costs.RouteCostModel(
            rows=learned_rows(*rows), version=len(rows) + 1)

    def plan(self, destination="/goal", **options):
        task = NavigateTask(self.graph, destination)
        for name, value in options.items():
            setattr(task, name, value)
        task.status = TaskStatus.RUNNING
        try:
            return task, [edge.destination for edge in task._plan(self.client)]
        except ValueError as error:
            return task, str(error)

    def rows(self):
        self.client.route_shadow.flush(self.client, force=True)
        return self.client.memory.route_shadow_rows("Sera")

    def test_the_live_plan_is_todays_and_the_shadow_logs_where_it_differs(self):
        self.learn((60, "map:/blocked", "death", 1.0))
        _, live = self.plan()
        shadow, self.client.route_shadow = self.client.route_shadow, None
        _, without = self.plan()
        self.client.route_shadow = shadow
        self.assertEqual(live, without)
        self.assertEqual(live, ["/blocked", "/goal"])
        self.assertEqual(self.client.actions(), [])
        shadow.run(self.client)
        record, = [r for r in self.client.decision_history
                   if r["action"] == "route-shadow-diverge"]
        self.assertIn("errand trip /start -> /goal: diverged", record["detail"])
        self.assertRegex(record["detail"], r"-179\d s learned danger")
        row, = self.rows()
        self.assertEqual((row["kind"], row["trip"], row["result"]), ("trip", "errand", "diverged"))
        detail = row["detail"]
        self.assertEqual(detail["live"]["maps"], ["/blocked", "/goal"])
        self.assertEqual(detail["shadow"]["maps"], ["/detour_1", "/detour_2", "/goal"])
        self.assertEqual(detail["live"]["worst"][0][0], "map:/blocked")
        self.assertEqual(detail["first_difference"]["index"], 0)
        summary = shadow.summary(self.client)
        self.assertEqual(summary["counts"], {"trip": {"errand": {"diverged": 1}}})
        self.assertEqual(summary["recent"][0]["result"], "diverged")
        self.assertFalse(summary["enabled"])

    def test_a_decline_and_an_override_are_logged(self):
        self.graph = blocks_graph(detour=False)
        self.learn((60, "map:/blocked", "death", 1.0), (0, "map:/blocked", "death", 1.0))
        self.plan()
        self.client.route_shadow.run(self.client)
        record = self.client.decision_history[-1]
        self.assertEqual(record["action"], "route-shadow-decline")
        self.assertIn("declined", record["detail"])
        self.assertIn("budget of 1800 s", record["detail"])
        self.client.route_shadow._next_trip = float("-inf")
        self.plan(essential="cure")
        self.client.route_shadow.run(self.client)
        record = self.client.decision_history[-1]
        self.assertEqual(record["action"], "route-shadow-decline")
        self.assertIn("cure trip /start -> /goal: override", record["detail"])
        self.assertIn("care bounded", record["detail"])
        self.assertEqual([row["result"] for row in self.rows()], ["declined", "override"])

    def test_an_agreement_is_counted_and_kept_without_a_decision(self):
        self.graph = blocks_graph(detour=False)
        self.plan()
        self.client.route_shadow.run(self.client)
        self.assertEqual(self.client.actions(), [])
        self.assertEqual([row["result"] for row in self.rows()], ["agreed"])

    def test_shadow_work_is_throttled_and_spread_over_steps(self):
        shadow = self.client.route_shadow
        self.learn((60, "map:/blocked", "death", 1.0))
        self.plan()
        self.assertIn("trip", shadow.jobs)
        # One in flight: another request is skipped.
        self.plan(destination="/detour_2")
        self.assertEqual(shadow.skipped, 1)
        # Each next() costs a second on this clock: a 0.5 s step advances
        # the search once, so it takes several steps.
        ticks = [0.0]

        def monotonic():
            ticks[0] += 1.0
            return ticks[0]

        shadow.monotonic = monotonic
        steps = 0
        while "trip" in shadow.jobs:
            shadow.step(self.client, budget=0.5)
            steps += 1
        self.assertGreater(steps, 3)
        # The same trip again is not compared again for a while.
        shadow.monotonic = time.monotonic
        shadow._next_trip = float("-inf")
        self.plan()
        self.assertNotIn("trip", shadow.jobs)
        self.assertEqual(shadow.skipped, 2)

    def test_shadow_failures_never_reach_the_tick(self):
        shadow = self.client.route_shadow

        def broken():
            yield
            raise RuntimeError("boom")

        shadow.jobs["trip"] = self.route_shadow._Job("trip", broken(), None, time.time())
        with self.assertLogs("atrinik_bot.route_shadow", "ERROR"):
            self.route_shadow.step(self.client, budget=1.0)
        self.assertEqual((shadow.jobs, shadow.dropped), ({}, 1))
        with patch.object(self.route_shadow.RouteShadow, "step", side_effect=RuntimeError("boom")), \
                self.assertLogs("atrinik_bot.route_shadow", "ERROR"):
            self.route_shadow.step(self.client)
        with patch.object(NavigateTask, "_trip_snapshot", side_effect=RuntimeError("x")), \
                self.assertLogs("atrinik_bot.route_shadow", "ERROR"):
            self.assertEqual(self.plan()[1], ["/blocked", "/goal"])

    def test_with_the_flag_on_nothing_runs_in_the_shadow(self):
        self.client.config.learned_route_costs = True
        self.plan()
        self.assertEqual(self.client.route_shadow.jobs, {})

    def test_a_planning_probe_and_the_walk_home_are_not_compared(self):
        task = NavigateTask(self.graph, "/goal")
        task._plan(self.client)
        self.assertEqual(self.client.route_shadow.jobs, {})

    def test_the_report_summarises_per_trip_kind(self):
        from .cli import parser, route_shadow_command
        self.learn((60, "map:/blocked", "death", 1.0))
        self.plan()
        self.client.route_shadow.run(self.client)
        self.client.route_shadow._next_trip = float("-inf")
        self.graph = blocks_graph(detour=False)
        self.plan(trip="farm")
        self.client.route_shadow.run(self.client)
        rows = self.rows()
        report = self.route_shadow.summarise_rows(rows)
        self.assertEqual(report["counts"], {"trip": {"errand": {"diverged": 1},
                                                     "farm": {"agreed": 1}}})
        self.assertEqual(report["subjects"][0], ("map:/blocked", 1))
        args = parser().parse_args([
            "--runtime-state", str(self.client.memory.path), "--host", "game",
            "--port", "1", "--account", "acct", "--character", "Sera", "route-shadow"])
        args.host, args.port = "game", None
        import contextlib
        import io
        out = io.StringIO()
        with patch.object(self.client.memory, "server", "game"), \
                contextlib.redirect_stdout(out):
            with patch("atrinik_bot.memory.BotMemory.open_read_only",
                       return_value=self.client.memory):
                self.assertEqual(route_shadow_command(args), 0)
        text = out.getvalue()
        self.assertIn("2 comparisons in the last 24 h", text)
        self.assertIn("errand", text)
        self.assertIn("diverged 1", text)
        self.assertIn("map:/blocked", text)

    def test_a_shadow_no_route_where_the_live_plan_failed_is_agreement(self):
        self.graph = blocks_graph(detour=False)
        self.graph.nodes["/blocked"].edges.clear()
        _, live = self.plan()
        self.assertIsInstance(live, str)
        self.client.route_shadow.run(self.client)
        self.assertEqual([row["result"] for row in self.rows()], ["agreed"])
        self.assertEqual(self.client.actions(), [])

    def test_a_zero_length_trip_is_no_comparison(self):
        # Already on the destination map: no edges, no error, nothing compared.
        _, live = self.plan(destination="/start")
        self.assertEqual(live, [])
        self.assertEqual(self.client.route_shadow.jobs, {})
        self.client.route_shadow.run(self.client)
        self.assertEqual((self.rows(), self.client.actions()), ([], []))

    def test_both_plans_empty_is_not_a_divergence(self):
        # Requested anyway (another destination name on this map): the
        # shadow's empty route agrees and nothing is recorded.
        shadow = self.client.route_shadow
        task = NavigateTask(self.graph, "/goal")
        task.status = TaskStatus.RUNNING
        plan = self.route_costs.LearnedPlan(trip="errand", outcome="planned", route=[])
        context = {"trip": "errand", "source": "/start", "destination": "/goal",
                   "strict": False, "live": (), "live_route": [], "error": "",
                   "live_failed": False,
                   "snapshot": task._trip_snapshot(self.client, None)}
        shadow._finish_trip(self.client, context, plan)
        self.assertEqual((self.rows(), self.client.actions(), shadow.counts), ([], [], {}))
        # A live failure beside it is still compared, with or without an error.
        shadow._finish_trip(self.client, {**context, "error": "no route",
                                          "live_failed": True}, plan)
        shadow._finish_trip(self.client, {**context, "live_failed": True}, plan)
        self.assertEqual([row["result"] for row in self.rows()], ["diverged", "diverged"])

    def test_a_failed_live_plan_without_an_error_is_compared(self):
        # A live plan that failed (no route) without an error text is no
        # zero-length trip, even from the destination map; a zero-length
        # one does not count as skipped.
        shadow = self.client.route_shadow
        task = NavigateTask(self.graph, "/start")
        task.status = TaskStatus.RUNNING
        shadow.jobs["trip"] = self.route_shadow._Job("trip", iter(()), None, time.time())
        shadow.request_trip(self.client, task, None, [], "")
        self.assertEqual(shadow.skipped, 0)
        shadow.request_trip(self.client, task, None, None, "")
        self.assertEqual(shadow.skipped, 1)
        shadow.jobs.clear()
        shadow.request_trip(self.client, task, None, None, "")
        self.assertIn("trip", shadow.jobs)
        shadow.run(self.client)
        self.assertEqual([row["result"] for row in self.rows()], ["diverged"])

    def test_the_report_ignores_stored_zero_length_rows(self):
        now = time.time()
        zero = {"at": now, "kind": "trip", "trip": "errand", "result": "diverged",
                "source": "/shattered_islands/world_0_83",
                "destination": "/shattered_islands/world_0_83", "reason": "",
                "outcome": "planned", "care": "", "budget": None,
                "live": {"edges": 0, "maps": []},
                "shadow": {"edges": 0, "maps": [], "time": 0, "prior": 0,
                           "learned": 0, "total": 0}}
        real = {**zero, "at": now + 1, "destination": "/goal",
                "live": {"edges": 1, "maps": ["/goal"]},
                "shadow": {"edges": 2, "maps": ["/detour_1", "/goal"]}}
        failed = {**zero, "at": now + 2, "live": {"edges": 0, "maps": [], "error": "no route"}}
        # Shadow failures store 0 edges too: they stay counted.
        no_route = {**zero, "at": now + 3, "result": "no_route", "outcome": "no_route",
                    "shadow": {"edges": 0, "maps": []}}
        declined = {**no_route, "at": now + 4, "result": "declined", "outcome": "declined"}
        # Both empty between two maps: not provably zero-length, kept.
        elsewhere = {**zero, "at": now + 5, "destination": "/goal"}
        self.client.memory.record_route_shadow(
            "Sera", [zero, real, failed, no_route, declined, elsewhere])
        report = self.route_shadow.summarise_rows(self.client.memory.route_shadow_rows("Sera"))
        self.assertEqual((report["rows"], report["zero_length"]), (5, 1))
        self.assertEqual(report["counts"], {"trip": {"errand": {
            "diverged": 3, "no_route": 1, "declined": 1}}})
        self.assertEqual([row["result"] for row in report["differences"]],
                         ["diverged", "diverged", "no_route", "declined", "diverged"])

    def test_each_job_progresses_every_step(self):
        shadow = self.client.route_shadow
        progress = {"trip": 0, "farm": 0}

        def job(kind):
            while True:
                progress[kind] += 1
                yield

        for kind in progress:
            shadow.jobs[kind] = self.route_shadow._Job(kind, job(kind), None, time.time())
        # Round robin: one leads each step, the other only with time left.
        shadow.step(self.client, budget=0.0)
        self.assertEqual(sorted(progress.values()), [0, 1])
        shadow.step(self.client, budget=0.0)
        self.assertEqual(progress, {"trip": 1, "farm": 1})

    def test_rows_stay_valid_json_capped_and_pruned(self):
        from . import route_events
        entry = {"at": time.time(), "kind": "trip", "trip": "errand", "result": "diverged",
                 "source": "/a", "destination": "/b", "reason": "x" * 9000,
                 "live": {"maps": ["/m" * 50] * 200}, "shadow": {"maps": []}}
        self.client.memory.record_route_shadow("Sera", [entry])
        row, = self.client.memory.route_shadow_rows("Sera")
        self.assertEqual(row["detail"]["result"], "diverged")
        self.assertLessEqual(len(json.dumps(row["detail"])), 8100)
        old = {**entry, "reason": "", "live": {}, "at": time.time() - route_events.SHADOW_MAX_AGE - 5}
        with patch.object(route_events, "SHADOW_ROW_CAP", 3):
            self.client.memory.record_route_shadow(
                "Sera", [old] + [{**entry, "reason": "", "live": {}, "at": time.time() + i}
                                 for i in range(5)])
        rows = self.client.memory.route_shadow_rows("Sera")
        self.assertEqual(len(rows), 3)
        self.assertTrue(all(row["at"] > time.time() - 60 for row in rows))

    def test_rows_are_written_while_idle_and_at_shutdown(self):
        shadow = self.client.route_shadow
        shadow.pending.append({"at": time.time(), "kind": "trip", "trip": "errand",
                               "result": "agreed"})
        shadow._next_flush = float("inf")
        self.route_shadow.close(self.client)
        self.assertEqual(len(self.client.memory.route_shadow_rows("Sera")), 1)
        shadow.pending.append({"at": time.time(), "kind": "trip", "trip": "errand",
                               "result": "agreed"})
        shadow._next_flush = float("-inf")
        self.route_shadow.step(self.client)
        self.assertEqual(len(self.client.memory.route_shadow_rows("Sera")), 2)

    def test_the_engine_steps_the_shadow_without_a_task(self):
        engine = TaskEngine(self.client, tick_rate=0.0)
        calls = []
        with patch.object(self.route_shadow, "step", lambda client: (
                calls.append(client), setattr(engine, "running", False))), \
                patch.object(self.route_shadow, "close", lambda client: calls.append("close")):
            engine.running = True
            asyncio.run(engine.run())
        self.assertEqual(calls, [self.client, "close"])

    def test_the_farm_shadow_weighs_danger_by_lambda(self):
        from .navigation import danger_weight
        self.client.state.farm_objective = "safety"
        self.assertEqual(danger_weight(self.client, optional=False), 2.0)

    def test_metrics_count_shadow_results(self):
        from .metrics import BotMetrics
        client = AtrinikClient(ClientConfig())
        metrics = BotMetrics(client)
        metrics.route_plan("shadow_diverged", "errand")
        client.route_shadow.last_cost = {"time": 12.0, "danger": 1800.0,
                                         "learned": 1800.0, "budget": 1800.0}
        text = metrics.render()
        self.assertIn('route_plans_total{', text)
        self.assertIn('result="shadow_diverged"', text)
        self.assertIn('trip="errand"', text)
        self.assertIn('route_plan_cost_seconds{', text)
        self.assertIn('part="learned"', text)


class RouteShadowContentTests(RouteDeathReachIsolation, unittest.TestCase):
    """docs/ROUTING.md 4.10, P6 accept: the incident replay and identical
    live plans on the locked content."""

    BED = "/shattered_islands/world_1_67_1"
    UC = "/shattered_islands/strakewood_island/underground_city/underground_city_"
    TREES = "/shattered_islands/world_14_79"

    def setUp(self):
        super().setUp()
        from . import route_costs
        self.route_costs = route_costs
        self.graph = built_graph()

    def sera(self, rankings=None):
        client = AtrinikClient(ClientConfig())
        client.state.phase = "playing"
        client.state.stats.update({"level": 34, "exp": 1000, "hp": 300, "maxhp": 300})
        point = self.graph.savebeds[self.BED][0]
        client.state.savebed_map, client.state.savebed_xy = self.BED, point
        client.state.map.path = self.BED
        client.state.map.world_x, client.state.map.world_y = point
        client.farm_analyzer = StubAnalyzer(rankings or {})
        return client

    def learn(self, client, *rows):
        client._route_cost_model = self.route_costs.RouteCostModel(
            rows=learned_rows(*rows), version=len(rows) + 1)
        client._route_cost_model_state = ("", time.monotonic(), 0)

    def test_the_incident_replay_leaves_the_underground_city_after_one_death(self):
        from .navigation import analyzer_farm_choice
        # The 2026-11-14 incident (section 2): the Underground City circuit
        # at 0_4 ranked first, a Burnt Forest circuit at 80 % of its rate
        # (the live rates were not recorded; 4.5 uses the condition).
        circuit = {**analyzer_spot("UC circuit", [self.UC + "0_4"], ["orc L30"]),
                   "xp_hour": 7.0e6}
        forest = {**analyzer_spot("Burnt forest", [self.TREES], ["evil treant L13"]),
                  "xp_hour": 5.6e6}
        client = self.sera({"xp": [circuit, forest]})
        shadow = client.route_shadow
        # 20:34:13: the Old Outpost death (resources), not on either route.
        self.learn(client, (900, "map:/shattered_islands/old_outpost/old_outpost_0101",
                            "death", 1.0))
        self.assertEqual(analyzer_farm_choice(client, self.graph)[2]["name"], "UC circuit")
        shadow.run(client)
        self.assertEqual((shadow.last_farm["result"], shadow.last_farm["shadow"]["name"]),
                         ("agreed", "UC circuit"))
        # 20:38:44: the first underground_city_0_0 death.
        self.learn(client, (900, "map:/shattered_islands/old_outpost/old_outpost_0101",
                            "death", 1.0), (0, f"map:{self.UC}0_0", "death", 1.0))
        shadow._farm = (None, float("-inf"))
        live = analyzer_farm_choice(client, self.graph)
        # The live choice stays #94's (no kit failure recorded here).
        self.assertEqual(live[2]["name"], "UC circuit")
        shadow.run(client)
        farm = shadow.last_farm
        self.assertEqual((farm["result"], farm["shadow"]["name"]), ("diverged", "Burnt forest"))
        self.assertEqual(round(farm["live"]["danger"]), 1800)
        self.assertEqual(farm["shadow"]["danger"], 0)
        self.assertTrue(any(record["action"] == "route-shadow-diverge" and
                            "farm: diverged" in record["detail"]
                            for record in client.decision_history))
        # A second death within 3.5 h pauses the circuit outright.
        self.learn(client, (3 * 3600, f"map:{self.UC}0_0", "death", 1.0),
                   (0, f"map:{self.UC}0_0", "death", 1.0))
        shadow._farm = (None, float("-inf"))
        analyzer_farm_choice(client, self.graph)
        shadow.run(client)
        self.assertIn("at its cap", shadow.last_farm["paused"][
            "xp:" + circuit["path"]])

    def test_with_the_flag_off_live_plans_and_farm_choices_are_unchanged(self):
        from . import route_shadow
        from .navigation import analyzer_farm_choice
        bed = self.graph.savebeds[self.BED][0]
        trips = (
            ((self.BED, *bed), self.UC + "0_4", {"allow_ranged_hazard_fallback": True}),
            ((self.BED, *bed), "/shattered_islands/world_6_51", {}),
            ((self.BED, *bed), self.TREES, {}),
            ((self.BED, *bed), "/shattered_islands/world_0_51", {"strict_safety": True}),
            ((self.BED, *bed), self.UC + "0_4", {"strict_safety": True}),
            (("/shattered_islands/world_0_70", 10, 10), "/shattered_islands/world_3_69",
             {"strict_safety": True}),
        )
        for (path, x, y), destination, options in trips:
            with self.subTest(destination=destination, **options):
                results = []
                for shadowed in (True, False):
                    client = self.sera()
                    client.state.map.path, client.state.map.world_x, \
                        client.state.map.world_y = path, x, y
                    self.learn(client, (0, f"map:{self.UC}0_0", "death", 1.0))
                    if not shadowed:
                        client.route_shadow = None
                    task = NavigateTask(self.graph, destination)
                    task.status = TaskStatus.RUNNING
                    for name, value in options.items():
                        setattr(task, name, value)
                    try:
                        results.append(task._plan(client))
                    except ValueError as error:
                        results.append(str(error))
                    if shadowed:
                        self.assertIn("trip", client.route_shadow.jobs)
                        client.route_shadow.run(client)
                        self.assertEqual(client.route_shadow.jobs, {})
                self.assertEqual(results[0], results[1])
        circuit = analyzer_spot("UC", [self.UC + "0_4"], ["orc L30"])
        forest = analyzer_spot("Forest", [self.TREES], ["evil treant L13"])
        choices = []
        for shadowed in (True, False):
            client = self.sera({"xp": [circuit, forest]})
            self.learn(client, (0, f"map:{self.UC}0_0", "death", 1.0))
            if not shadowed:
                client.route_shadow = None
            choices.append(analyzer_farm_choice(client, self.graph))
            if shadowed:
                route_shadow.shadow(client).run(client)
        self.assertEqual(choices[0], choices[1])

    def test_strict_shadow_plans_route_where_todays_strict_plans_do(self):
        from .navigation import learned_route
        bed = self.graph.savebeds[self.BED][0]
        for destination in ("/shattered_islands/world_0_51", "/shattered_islands/world_6_51",
                            self.UC + "0_4", "/shattered_islands/world_0_70"):
            with self.subTest(destination):
                client = self.sera()
                task = NavigateTask(self.graph, destination)
                task.strict_safety = True
                try:
                    live = task._plan(client)
                except ValueError:
                    live = None
                plan = self.route_costs.drain(learned_route(task._trip_snapshot(client)))
                self.assertEqual(plan.route is not None, live is not None)
                if live is not None:
                    avoided = task._trip_snapshot(client).strict_avoided
                    self.assertFalse({edge.destination for edge in plan.route[:-1]} & avoided)


class HealsLandInMeleeTests(unittest.TestCase):
    """The 2026-11-23 Underground City death: in melee, each auto-swing set
    her action timer for her weapon speed (2.25 s, server types/player.c),
    socket_command_fire dropped every cast sent while it ran, and her
    safety policy, healing every 1.15 s with combat on, counted each
    dropped cast as a heal (about 8 of 25 landed; her SP stayed at 82)."""

    WEAPON_SPEED = 2.25
    CAST_TIME = 1.0
    TICK = 0.1

    class Clock:
        def __init__(self):
            self.now = 1000.0

        def __call__(self):
            return self.now

    class Server:
        """A melee the client sees: auto-swings while combat is on, FIRE
        dropped without a word while the action timer runs, applies never
        gated, and a hit 3 HP every tick so she stays under the heal
        threshold."""

        def __init__(self, test, client, clock, hit=3):
            self.test, self.client, self.clock, self.hit = (
                test, client, clock, hit)
            self.action_until = 0.0
            self.combat = True
            self.swings = 0
            self.fires = []
            self.landed = []
            client.state.combat = True

        def set_timer(self, seconds):
            now = self.clock.now
            self.action_until = now + seconds
            self.client.state.stats["action_time"] = seconds
            self.client.state.stat_observed_at["action_time"] = now

        def tick(self):
            now = self.clock.now
            if self.combat and now >= self.action_until:
                self.swings += 1
                self.set_timer(HealsLandInMeleeTests.WEAPON_SPEED)
            stats = self.client.state.stats
            stats["hp"] = max(1, stats["hp"] - self.hit)

        def heal(self, amount=15):
            stats = self.client.state.stats
            stats["hp"] = min(stats["maxhp"], stats["hp"] + amount)
            self.client.state.add_message(
                0, "white", f"The spell heals you for {amount} hp!")
            self.landed.append(self.clock.now)

        async def fire(self, direction, tag=0):
            self.fires.append(self.clock.now)
            if self.clock.now < self.action_until:
                return  # socket_command_fire: action_attack still running
            item = self.client.state.items.get(tag)
            if item is not None and item.item_type == c.TYPE_SPELL:
                self.client.state.stats["sp"] -= 4
            self.heal()
            self.set_timer(HealsLandInMeleeTests.CAST_TIME)

        async def apply(self, tag):
            state = self.client.state
            item = state.items.get(tag)
            self.client.applied.append(tag)
            if item is None:
                return
            if item.item_type in (c.TYPE_ROD, c.TYPE_WAND):
                item.flags ^= c.ITEM_APPLIED
                return
            item.quantity -= 1
            if not item.quantity:
                state.remove_item(tag)
            self.heal(30)

        async def set_combat(self, enabled, force=False):
            self.combat = bool(enabled or force)
            self.client.combat.append(enabled)
            # The server answers with its target packet.
            self.client.state.combat = self.combat

    def setUp(self):
        self.clock = self.Clock()
        patcher = patch("time.monotonic", self.clock)
        patcher.start()
        self.addCleanup(patcher.stop)

    def melee(self, *heals, hp=150, sp=82, hit=3):
        client = types.SimpleNamespace()
        client.state = GameState(phase="playing", player_tag=7)
        client.state.stats.update(hp=hp, maxhp=330, sp=sp, food=999,
                                  level=36)
        for item in heals:
            client.state.place_item(item, 7)
        client.applied = []
        client.combat = []
        client.decisions = []
        server = self.Server(self, client, self.clock, hit=hit)
        client.fire = server.fire
        client.apply = server.apply
        client.set_combat = server.set_combat

        async def clear_actions():
            pass

        client.clear_actions = clear_actions
        client.record_action = lambda action, detail="": (
            client.decisions.append((action, detail)))
        # The melee is under way: her last swing just went.
        server.set_timer(self.WEAPON_SPEED)
        return client, server

    def run_for(self, client, server, policy, seconds):
        for _ in range(int(round(seconds / self.TICK))):
            server.tick()
            asyncio.run(policy.enforce(client))
            self.clock.now += self.TICK

    @staticmethod
    def spell():
        spell = Item(24, item_type=c.TYPE_SPELL, name="minor healing")
        spell.extra["cost"] = 4
        return spell

    def test_heals_land_through_the_swing_timer(self):
        client, server = self.melee(self.spell(), hit=1)
        policy = SafetyPolicy()
        self.run_for(client, server, policy, 30.0)
        # Every cast she sent landed: none went out while the timer ran.
        self.assertEqual(len(server.fires), len(server.landed))
        self.assertGreaterEqual(len(server.landed), 9)
        self.assertEqual(client.state.stats["sp"], 82 - 4 * len(server.landed))
        self.assertNotIn("heal-unconfirmed",
                         [action for action, _ in client.decisions])
        # She fought back between heals: swings went on.
        self.assertGreaterEqual(server.swings, 5)
        # The cooldown counts from a heal that landed.
        self.assertIn(policy._last_heal, server.landed)

    def test_combat_comes_back_on_with_each_cast(self):
        from .tasks import heal_waiting
        client, server = self.melee(self.spell())
        policy = SafetyPolicy()
        asyncio.run(policy.enforce(client))
        # Timer running: combat off, nothing sent, and the tick is not the
        # heal's: callers may step away meanwhile, but not fight.
        self.assertEqual(client.combat, [False])
        self.assertEqual(server.fires, [])
        self.assertEqual(policy._heal_action, 0.0)
        self.assertTrue(heal_waiting(client))
        # One server tick of margin past the client's countdown.
        self.clock.now += self.WEAPON_SPEED
        asyncio.run(policy.enforce(client))
        self.assertEqual(server.fires, [])
        self.clock.now += 0.2
        asyncio.run(policy.enforce(client))
        self.assertFalse(heal_waiting(client))
        self.assertEqual(policy._heal_action, self.clock.now)
        self.assertEqual(len(server.landed), 1)
        # The fire went first, then combat came back on.
        self.assertEqual(client.combat, [False, True])
        self.assertTrue(server.combat)
        self.assertIsNone(getattr(client, "heal_combat_force", None))

    def test_no_combat_off_outlives_a_heal_no_longer_needed(self):
        client, server = self.melee(self.spell())
        policy = SafetyPolicy()
        asyncio.run(policy.enforce(client))
        self.assertFalse(server.combat)
        # A potion from elsewhere (or regeneration) lifted her over the
        # threshold before the timer ran out: no cast, combat back on.
        client.state.stats["hp"] = 300
        self.clock.now += 0.5
        self.assertTrue(asyncio.run(policy.enforce(client)))
        self.assertEqual(server.fires, [])
        self.assertTrue(server.combat)
        # Out of mana mid-wait: the same.
        client.state.stats.update(hp=150, sp=82)
        asyncio.run(policy.enforce(client))
        self.assertFalse(server.combat)
        client.state.stats["sp"] = 0
        asyncio.run(policy.enforce(client))
        self.assertTrue(server.combat)

    def test_a_recall_waiting_keeps_combat_off(self):
        client, server = self.melee(self.spell())
        policy = SafetyPolicy()
        asyncio.run(policy.enforce(client))
        self.assertFalse(server.combat)
        # The recall took over (recall_waiting): healing spells wait, and
        # the heal's combat-off is not undone.
        client.recall_waiting_until = self.clock.now + 1.0
        asyncio.run(policy.enforce(client))
        self.assertFalse(server.combat)
        self.assertIsNone(getattr(client, "heal_combat_force", None))

    def test_a_dropped_cast_is_retried_and_not_counted(self):
        client, server = self.melee(self.spell())
        policy = SafetyPolicy()
        # The client's timer ran out, but the server's has not: dropped.
        client.state.stats["action_time"] = 0
        server.combat = client.state.combat = False
        asyncio.run(policy.enforce(client))
        self.assertEqual(len(server.fires), 1)
        self.assertEqual(server.landed, [])
        self.assertEqual(policy._last_heal, 0.0)
        self.assertTrue(policy.heal_in_flight())
        # Not before the answer is due ...
        self.clock.now += 0.5
        asyncio.run(policy.enforce(client))
        self.assertEqual(len(server.fires), 1)
        # ... then again at once, without a full cooldown from the answer.
        self.clock.now += 0.6
        server.action_until = 0.0
        asyncio.run(policy.enforce(client))
        self.assertEqual(len(server.fires), 2)
        self.assertEqual(len(server.landed), 1)
        self.assertIn(("heal-unconfirmed", "via minor healing"),
                      client.decisions)
        self.clock.now += 0.2
        asyncio.run(policy.enforce(client))
        self.assertEqual(policy._last_heal, server.landed[0])
        self.assertFalse(policy.heal_in_flight())

    def test_a_potion_goes_at_once_with_combat_on(self):
        potion = Item(27, item_type=c.TYPE_POTION, quality=100,
                      name="potion of minor healing", quantity=3)
        client, server = self.melee(potion)
        policy = SafetyPolicy()
        asyncio.run(policy.enforce(client))
        # No timer gates an apply: drunk at once, combat left on.
        self.assertEqual(client.applied, [27])
        self.assertEqual(client.combat, [])
        self.assertTrue(server.combat)
        self.clock.now += 0.1
        asyncio.run(policy.enforce(client))
        self.assertEqual(policy._last_heal, server.landed[0])
        self.run_for(client, server, policy, 3.0)
        self.assertEqual(client.combat, [])
        self.assertEqual(client.applied, [27, 27, 27])
        self.assertEqual(len(server.landed), 3)

    def test_a_critical_heal_drinks_the_biggest_potion_before_casting(self):
        # Below her flee threshold a potion goes at once, while a cast
        # waits for her swing; greater healing before minor. Above it the
        # spell comes first and the potions are kept.
        minor = Item(27, item_type=c.TYPE_POTION, quality=100,
                     name="potion of minor healing (lvl 20)", quantity=2)
        greater = Item(28, item_type=c.TYPE_POTION, quality=100,
                       name="potion of greater healing (lvl 10)")
        client, server = self.melee(minor, self.spell(), greater, hp=150)
        policy = SafetyPolicy()
        # Not under attack (say, resting after the fight): the spell.
        self.assertEqual(policy._usable_heal(client).tag, 24)
        client.state.add_message(
            2, "ffffff", "charred treant hit you for 30 (-26) impact damage.")
        asyncio.run(policy.enforce(client))
        self.assertEqual(client.applied, [28])
        self.assertEqual(server.fires, [])
        self.assertEqual(client.combat, [])
        client, server = self.melee(minor, self.spell(), greater, hp=210)
        self.assertEqual(SafetyPolicy()._usable_heal(client).tag, 24)
        # Out of SP for the spell and out of combat, no potion: she
        # regenerates. Under attack the potion heals.
        client.state.stats["sp"] = 0
        self.assertIsNone(SafetyPolicy()._usable_heal(client))
        client.state.add_message(
            2, "ffffff", "charred treant hit you for 30 (-26) impact damage.")
        self.assertEqual(SafetyPolicy()._usable_heal(client).tag, 28)
        # A rest on an adapted margin (flee 89%), no SP and no contact:
        # from 60% up no potion, she regenerates.
        for hp in (200, 290):
            client, server = self.melee(minor, self.spell(), greater, hp=hp,
                                        sp=0)
            self.assertIsNone(SafetyPolicy(
                heal_below=0.98, flee_below=0.89)._usable_heal(client))
        # Broken away at 30% with no SP: the potion too.
        client, server = self.melee(minor, self.spell(), greater, hp=100,
                                    sp=0)
        self.assertEqual(SafetyPolicy()._usable_heal(client).tag, 28)

    def test_one_attacker_on_an_adapted_margin_gets_the_spell(self):
        # The Burnt Forest's adapted flee threshold is 89%: one treant at
        # 85% is what the spell is for, or she drinks four potions a kill.
        minor = Item(27, item_type=c.TYPE_POTION, quality=100,
                     name="potion of minor healing (lvl 20)", quantity=2)
        client, server = self.melee(minor, self.spell(), hp=280)
        policy = SafetyPolicy(heal_below=0.98, flee_below=0.89)
        client.state.add_message(
            2, "ffffff", "charred treant hit you for 30 (-26) impact damage.")
        self.assertEqual(policy._usable_heal(client).tag, 24)
        # Two kinds hitting her: the potion goes first.
        client.state.add_message(
            2, "ffffff", "singed sapling hit you for 28 (-33) cleave damage.")
        self.assertEqual(policy._usable_heal(client).tag, 27)
        # A bystander of another kind beside her (not hitting her), and
        # the attacker's tile listed twice: still one attacker.
        client, server = self.melee(minor, self.spell(), hp=280)
        client.state.map.tile(9, 8).objects[3] = MapObject(
            3, 300, 0, 0, name="charred treant", target_id=300,
            target_hp=100)
        client.state.map.tile(9, 8).objects[4] = MapObject(
            3, 300, 0, 0, name="charred treant", target_id=300,
            target_hp=100)
        client.state.map.tile(7, 8).objects[3] = MapObject(
            3, 301, 0, 0, name="kobold", target_id=301, target_hp=100)
        client.state.add_message(
            2, "ffffff", "charred treant hit you for 30 (-26) impact damage.")
        self.assertEqual(policy._usable_heal(client).tag, 24)
        # Three treants of one name beside her: three attackers, not one.
        client, server = self.melee(minor, self.spell(), hp=280)
        for tag, (x, y) in enumerate(((9, 8), (7, 8), (8, 9)), start=300):
            client.state.map.tile(x, y).objects[3] = MapObject(
                3, tag, 0, 0, name="charred treant", target_id=tag,
                target_hp=100)
        client.state.add_message(
            2, "ffffff", "charred treant hit you for 30 (-26) impact damage.")
        self.assertEqual(policy._usable_heal(client).tag, 27)
        # One attacker but at 60%: truly critical.
        client, server = self.melee(minor, self.spell(), hp=198)
        client.state.add_message(
            2, "ffffff", "charred treant hit you for 30 (-26) impact damage.")
        self.assertEqual(policy._usable_heal(client).tag, 27)

